final_template:
data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  queue_name   = "notificationQueue"
  account_id   = data.aws_caller_identity.current.account_id
  account_root = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
}

resource "aws_kms_key" "notification_queue" {
  description             = "Customer managed KMS key for encryption of the ${local.queue_name} SQS queue"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableRootAccountAccess"
        Effect    = "Allow"
        Principal = { AWS = local.account_root }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowSQSEncryption"
        Effect    = "Allow"
        Principal = { Service = "sqs.amazonaws.com" }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "notification_queue" {
  name          = "alias/${local.queue_name}"
  target_key_id = aws_kms_key.notification_queue.key_id
}

resource "aws_sqs_queue" "notification_queue" {
  name                       = local.queue_name
  delay_seconds              = 0
  max_message_size           = 2048
  message_retention_seconds  = 345600
  visibility_timeout_seconds = 30

  kms_master_key_id                 = aws_kms_key.notification_queue.arn
  kms_data_key_reuse_period_seconds = 300

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sqs_queue_policy" "notification_queue" {
  queue_url = aws_sqs_queue.notification_queue.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCurrentAccountQueueOperations"
        Effect    = "Allow"
        Principal = { AWS = local.account_root }
        Action = [
          "sqs:SendMessage",
          "sqs:ReceiveMessage",
          "sqs:DeleteMessage",
          "sqs:GetQueueAttributes"
        ]
        Resource = aws_sqs_queue.notification_queue.arn
      }
    ]
  })
}

terraform {
  required_providers {
    null = {
      source  = "hashicorp/null"
      version = "3.2.2"
    }
  }
}

variable "framework_name" {
  description = "Name of the AWS Backup framework."
  type        = string
  default     = "benchmark"
}

variable "framework_description" {
  description = "Description of the AWS Backup framework."
  type        = string
  default     = "benchmark"
}

variable "tag_key" {
  description = "Tag key applied to the AWS Backup framework."
  type        = string
  default     = "BenchmarkTag"
}

resource "null_resource" "benchmark" {
  triggers = {
    name = var.framework_name
  }
}

resource "aws_backup_framework" "benchmark" {
  name        = var.framework_name
  description = var.framework_description

  control {
    name = "BACKUP_RESOURCES_PROTECTED_BY_BACKUP_PLAN"

    scope {
      compliance_resource_types = ["EBS"]
    }
  }

  tags = {
    (var.tag_key) = null_resource.benchmark.id
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

locals {
  kms_key_alias = "alias/bar"
}

resource "aws_kms_key" "bar" {
  description             = "Symmetric key for general encryption and decryption tasks"
  key_usage               = "ENCRYPT_DECRYPT"
  deletion_window_in_days = 10
  enable_key_rotation     = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "bar" {
  name          = local.kms_key_alias
  target_key_id = aws_kms_key.bar.key_id
}

data "aws_iam_policy_document" "bar" {
  statement {
    sid    = "AllowAllPrincipalsAllActions"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }
}

resource "aws_kms_key_policy" "bar" {
  key_id = aws_kms_key.bar.id
  policy = data.aws_iam_policy_document.bar.json
}

locals {
  vpc_cidr = "10.0.0.0/16"
  vpc_name = "main"
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = local.vpc_name
  }
}

resource "aws_security_group" "alb" {
  name        = "alb"
  description = "Accept inbound HTTP from any IP address; allow outbound only within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from any IP address"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Outbound traffic within the VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "alb"
  }
}

resource "aws_security_group" "allow_alb" {
  name        = "allow_alb"
  description = "Accept inbound HTTP exclusively from the ALB security group; allow outbound only within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "HTTP from the ALB security group"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "Outbound traffic within the VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "allow_alb"
  }
}

data "aws_partition" "current" {}

locals {
  role_name = "lambda-efs-vpc-execution-role"

  # Well-known AWS-managed policy ARNs, scoped to the current partition.
  lambda_vpc_access_policy_arn       = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSLambdaVPCAccessExecutionRole"
  efs_client_full_access_policy_arn  = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonElasticFileSystemClientFullAccess"
}

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    sid     = "LambdaServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "lambda_execution" {
  name                 = local.role_name
  description          = "Execution role for a Lambda function running in a VPC and accessing Amazon EFS"
  assume_role_policy   = data.aws_iam_policy_document.lambda_assume_role.json
  max_session_duration = 3600

  tags = {
    Name = local.role_name
  }
}

resource "aws_iam_role_policy_attachment" "lambda_vpc_access" {
  role       = aws_iam_role.lambda_execution.name
  policy_arn = local.lambda_vpc_access_policy_arn
}

resource "aws_iam_role_policy_attachment" "efs_client_full_access" {
  role       = aws_iam_role.lambda_execution.name
  policy_arn = local.efs_client_full_access_policy_arn
}

###############################################################################
# Variables
###############################################################################

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet."
  type        = string
  default     = "10.0.1.0/24"
}

variable "instance_id" {
  description = "EC2 instance ID to associate with the Elastic IP. Defaults to an empty string (no instance association)."
  type        = string
  default     = ""
}

variable "project_name" {
  description = "Name used to prefix and tag the networking resources."
  type        = string
  default     = "public-stack"
}

###############################################################################
# Local values
###############################################################################

locals {
  common_tags = {
    Project     = var.project_name
    ManagedBy   = "Terraform"
    Environment = "public"
  }
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

###############################################################################
# Networking
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-vpc"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-public-subnet"
    Tier = "Public"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Elastic IP (optionally associated with an EC2 instance)
###############################################################################

resource "aws_eip" "public" {
  domain   = "vpc"
  instance = var.instance_id != "" ? var.instance_id : null

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-eip"
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "public_subnet_id" {
  description = "ID of the public subnet."
  value       = aws_subnet.public.id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway attached to the VPC."
  value       = aws_internet_gateway.main.id
}

output "public_route_table_id" {
  description = "ID of the public route table routing 0.0.0.0/0 to the internet gateway."
  value       = aws_route_table.public.id
}

output "eip_allocation_id" {
  description = "Allocation ID of the Elastic IP."
  value       = aws_eip.public.id
}

output "eip_public_ip" {
  description = "Public IP address of the Elastic IP."
  value       = aws_eip.public.public_ip
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_cidr             = "10.0.0.0/16"
  public_subnet_cidr   = "10.0.1.0/24"
  private_subnet_cidr  = "10.0.2.0/24"
  availability_zone    = data.aws_availability_zones.available.names[0]
  name_prefix          = "network-test"
  public_subnet_ipv6   = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, 0)
}

resource "aws_vpc" "main" {
  cidr_block                       = local.vpc_cidr
  assign_generated_ipv6_cidr_block = true

  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_subnet_cidr
  availability_zone = local.availability_zone
  ipv6_cidr_block   = local.public_subnet_ipv6

  tags = {
    Name = "${local.name_prefix}-public-subnet"
    Tier = "public"
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidr
  availability_zone = local.availability_zone

  tags = {
    Name = "${local.name_prefix}-private-subnet"
    Tier = "private"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-public-rt"
  }
}

resource "aws_route" "public_ipv4_default" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "public_ipv6_default" {
  route_table_id              = aws_route_table.public.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id

  # Suffix for the single standalone bucket.
  standalone_bucket_suffix = "bucket2"

  # Suffixes consumed by the count-based bucket set.
  count_bucket_suffixes = ["bucket3", "bucket4"]

  # Suffixes consumed by the for_each collection.
  collection_bucket_suffixes = ["bucket101", "bucket102", "bucket103", "bucket104"]

  # Map projection of the suffix list, used with for_each.
  collection_buckets = {
    for suffix in local.collection_bucket_suffixes : suffix => {
      suffix = suffix
    }
  }
}

# Single shared customer-managed KMS key used for default SSE-KMS encryption.
resource "aws_kms_key" "bucket" {
  description             = "Customer managed KMS key for S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "AllowAccountRootKeyAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${local.account_id}:root"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:CreateGrant",
      "kms:ListGrants",
      "kms:RevokeGrant",
      "kms:GetKeyPolicy",
      "kms:PutKeyPolicy",
      "kms:GetKeyRotationStatus",
      "kms:EnableKeyRotation",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:ListResourceTags",
      "kms:ScheduleKeyDeletion",
      "kms:CancelKeyDeletion",
    ]

    resources = ["*"]
  }
}

# ---------------------------------------------------------------------------
# Standalone bucket (suffix "bucket2")
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "standalone" {
  bucket = "${local.account_id}-${local.standalone_bucket_suffix}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "standalone" {
  bucket = aws_s3_bucket.standalone.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "standalone" {
  bucket = aws_s3_bucket.standalone.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.bucket.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

# ---------------------------------------------------------------------------
# Count-based buckets (suffixes "bucket3" and "bucket4")
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "count_based" {
  count = length(local.count_bucket_suffixes)

  bucket = "${local.account_id}-${local.count_bucket_suffixes[count.index]}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "count_based" {
  count = length(aws_s3_bucket.count_based)

  bucket = aws_s3_bucket.count_based[count.index].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "count_based" {
  count = length(aws_s3_bucket.count_based)

  bucket = aws_s3_bucket.count_based[count.index].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.bucket.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

# ---------------------------------------------------------------------------
# Collection buckets (suffixes "bucket101" - "bucket104")
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "collection" {
  for_each = local.collection_buckets

  bucket = "${local.account_id}-${each.value.suffix}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "collection" {
  for_each = aws_s3_bucket.collection

  bucket = each.value.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "collection" {
  for_each = aws_s3_bucket.collection

  bucket = each.value.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.bucket.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

locals {
  budget_name         = "budget"
  budget_limit_amount = "25.0"
  budget_limit_unit   = "USD"
  budget_time_start   = "2021-07-01_00:00"
  budget_time_unit    = "MONTHLY"

  alert_email = "hello@chriswilding.co.uk"
  alert_phone = "+447828835419"

  budgets_service = "budgets.amazonaws.com"
  sns_service     = "sns.amazonaws.com"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

# -----------------------------------------------------------------------------
# Customer managed KMS key used to encrypt the SNS topic. The AWS Budgets
# service is explicitly allowed to use the key so it can publish notifications.
# -----------------------------------------------------------------------------
resource "aws_kms_key" "budget" {
  description             = "Customer managed key for the AWS Budgets notification SNS topic"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowBudgetsServiceToUseKey"
        Effect = "Allow"
        Principal = {
          Service = local.budgets_service
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowSnsServiceToUseKey"
        Effect = "Allow"
        Principal = {
          Service = local.sns_service
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "budget" {
  name          = "alias/${local.budget_name}"
  target_key_id = aws_kms_key.budget.key_id
}

# -----------------------------------------------------------------------------
# SNS topic that AWS Budgets publishes to, encrypted with the CMK above.
# -----------------------------------------------------------------------------
resource "aws_sns_topic" "budget" {
  name              = local.budget_name
  kms_master_key_id = aws_kms_key.budget.arn
}

# -----------------------------------------------------------------------------
# Topic policy allowing the AWS Budgets service principal to publish.
# -----------------------------------------------------------------------------
resource "aws_sns_topic_policy" "budget" {
  arn = aws_sns_topic.budget.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowBudgetsServiceToPublish"
        Effect = "Allow"
        Principal = {
          Service = local.budgets_service
        }
        Action   = "SNS:Publish"
        Resource = aws_sns_topic.budget.arn
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      },
      {
        Sid    = "AllowOwnerAccountManagement"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = [
          "SNS:GetTopicAttributes",
          "SNS:SetTopicAttributes",
          "SNS:AddPermission",
          "SNS:RemovePermission",
          "SNS:DeleteTopic",
          "SNS:Subscribe",
          "SNS:ListSubscriptionsByTopic",
          "SNS:Publish"
        ]
        Resource = aws_sns_topic.budget.arn
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# SMS subscription on the topic for the on-call phone number.
# -----------------------------------------------------------------------------
resource "aws_sns_topic_subscription" "budget_sms" {
  topic_arn = aws_sns_topic.budget.arn
  protocol  = "sms"
  endpoint  = local.alert_phone
}

# -----------------------------------------------------------------------------
# Monthly cost budget with an actual-cost notification at 100% of the limit.
# -----------------------------------------------------------------------------
resource "aws_budgets_budget" "budget" {
  name              = local.budget_name
  budget_type       = "COST"
  limit_amount      = local.budget_limit_amount
  limit_unit        = local.budget_limit_unit
  time_period_start = local.budget_time_start
  time_unit         = local.budget_time_unit

  notification {
    comparison_operator        = "GREATER_THAN"
    threshold                  = 100
    threshold_type             = "PERCENTAGE"
    notification_type          = "ACTUAL"
    subscriber_email_addresses = [local.alert_email]
    subscriber_sns_topic_arns  = [aws_sns_topic.budget.arn]
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

data "aws_partition" "current" {}

locals {
  ecr_repository_name  = "reactjs-app-repo"
  ecs_task_role_name   = "ecsTaskExecutionRole"
  ecs_tasks_trusted_service = "ecs-tasks.amazonaws.com"

  ecs_task_execution_policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

# ---------------------------------------------------------------------------
# ECR repository for the React application container images
# ---------------------------------------------------------------------------
resource "aws_ecr_repository" "reactjs_app" {
  name                 = local.ecr_repository_name
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  encryption_configuration {
    encryption_type = "AES256"
  }

  tags = {
    Name        = local.ecr_repository_name
    Application = "reactjs-app"
    ManagedBy   = "terraform"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# IAM role assumed by ECS tasks
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "ecs_task_assume_role" {
  statement {
    sid     = "AllowEcsTasksToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = [local.ecs_tasks_trusted_service]
    }
  }
}

resource "aws_iam_role" "ecs_task_execution_role" {
  name               = local.ecs_task_role_name
  assume_role_policy = data.aws_iam_policy_document.ecs_task_assume_role.json

  tags = {
    Name        = local.ecs_task_role_name
    Application = "reactjs-app"
    ManagedBy   = "terraform"
  }
}

resource "aws_iam_role_policy_attachment" "ecs_task_execution_role_policy" {
  role       = aws_iam_role.ecs_task_execution_role.name
  policy_arn = local.ecs_task_execution_policy_arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

locals {
  role_name         = "role"
  allow_policy_1    = "allow-policy-1"
  allow_policy_2    = "allow-policy-2"
  ec2_service_principal = "ec2.amazonaws.com"
  pass_role_action  = "iam:PassRole"
  lambda_actions = [
    "lambda:CreateFunction",
    "lambda:InvokeFunc*",
  ]
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "AllowEC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = [local.ec2_service_principal]
    }
  }
}

resource "aws_iam_role" "role" {
  name               = local.role_name
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = {
    Name = local.role_name
  }
}

data "aws_iam_policy_document" "allow_policy_1" {
  statement {
    sid       = "AllowPassRole"
    effect    = "Allow"
    actions   = [local.pass_role_action]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "allow_policy_1" {
  name   = local.allow_policy_1
  role   = aws_iam_role.role.id
  policy = data.aws_iam_policy_document.allow_policy_1.json
}

data "aws_iam_policy_document" "allow_policy_2" {
  statement {
    sid       = "AllowLambdaCreateAndInvoke"
    effect    = "Allow"
    actions   = local.lambda_actions
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "allow_policy_2" {
  name   = local.allow_policy_2
  role   = aws_iam_role.role.id
  policy = data.aws_iam_policy_document.allow_policy_2.json
}

locals {
  efs_creation_token = "efs-not-secure"
  efs_name_tag       = "NotSecure"
}

resource "aws_efs_file_system" "not_secure" {
  creation_token = local.efs_creation_token
  encrypted      = true

  tags = {
    Name = local.efs_name_tag
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_efs_file_system_policy" "not_secure" {
  file_system_id = aws_efs_file_system.not_secure.id

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "ExamplePolicy01"
    Statement = [
      {
        Sid       = "ExampleStatement01"
        Effect    = "Allow"
        Principal = { AWS = "*" }
        Action    = "elasticfilesystem:*"
        Resource  = "*"
      }
    ]
  })
}

###############################################################################
# Terraform Remote Backend Infrastructure
#
# Provisions:
#   - Amazon S3 bucket for Terraform state storage (versioned, KMS encrypted,
#     fully blocked from public access)
#   - Customer-managed KMS key with automatic rotation for state encryption
#   - DynamoDB table for Terraform state locking
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

locals {
  # Requested base names for the remote state resources.
  state_bucket_name_base = "terraform-remote-state-storage-s3-kjg"
  lock_table_name_base   = "terraform-state-lock-dynamo"

  # S3 bucket names share a single global namespace and DynamoDB table names are
  # unique per account/region. A short random suffix keeps each deployment from
  # colliding with an existing bucket/table while preserving the requested base
  # names as the prefix.
  name_suffix = substr(uuid(), 0, 8)

  state_bucket_name = "${local.state_bucket_name_base}-${local.name_suffix}"
  lock_table_name   = "${local.lock_table_name_base}-${local.name_suffix}"

  caller_account_arn = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
}

###############################################################################
# KMS key dedicated to encrypting the Terraform state bucket
###############################################################################

data "aws_iam_policy_document" "terraform_state_key" {
  statement {
    sid    = "AllowAccountRootFullKeyManagement"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.caller_account_arn]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:DescribeKey",
      "kms:CreateGrant",
      "kms:ListGrants",
      "kms:RevokeGrant",
      "kms:GetKeyPolicy",
      "kms:PutKeyPolicy",
      "kms:GetKeyRotationStatus",
      "kms:EnableKeyRotation",
      "kms:DisableKeyRotation",
      "kms:ScheduleKeyDeletion",
      "kms:CancelKeyDeletion",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:ListResourceTags",
      "kms:ListAliases",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "terraform_state" {
  description             = "Customer-managed KMS key used to encrypt Terraform remote state"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.terraform_state_key.json
}

###############################################################################
# S3 bucket for Terraform state storage
###############################################################################

resource "aws_s3_bucket" "terraform_state" {
  bucket = local.state_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.terraform_state.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

###############################################################################
# DynamoDB table for Terraform state locking
###############################################################################

resource "aws_dynamodb_table" "terraform_lock" {
  name           = local.lock_table_name
  billing_mode   = "PROVISIONED"
  read_capacity  = 20
  write_capacity = 20

  hash_key = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

locals {
  log_group_name_prefix = "log-group-"
}

# Dynamically generated two-word pet name identifier (e.g. "sunny-otter").
resource "random_pet" "log_group" {
  length    = 2
  separator = "-"
}

resource "aws_cloudwatch_log_group" "this" {
  name              = "${local.log_group_name_prefix}${random_pet.log_group.id}"
  retention_in_days = 90

  tags = {
    Name        = "${local.log_group_name_prefix}${random_pet.log_group.id}"
    ManagedBy   = "terraform"
    Environment = "production"
  }

  lifecycle {
    prevent_destroy = true
  }
}

locals {
  project     = "Website CV"
  environment = "production"

  tags = {
    Project     = local.project
    Environment = local.environment
  }

  delegation_set_reference_name = "WebsiteDNS"
  delegation_set_parameter_name = "/WebsiteCv/production/Route53/DelegationSetId"
}

resource "aws_route53_delegation_set" "website" {
  reference_name = local.delegation_set_reference_name
}

resource "aws_ssm_parameter" "delegation_set_id" {
  name  = local.delegation_set_parameter_name
  type  = "String"
