    prevent_destroy = true
  }
}

variable "bucket_name" {
  description = "Name of the S3 bucket used for benchmarking."
  type        = string
  default     = "benchmark-bucket-tf5x"
}

variable "name_tag" {
  description = "Value applied to the Name tag of the created resources."
  type        = string
  default     = "benchmark"
}

variable "force_destroy" {
  description = "Enable forced destruction so the bucket can be removed even when it contains objects."
  type        = bool
  default     = true
}

locals {
  common_tags = {
    Name = var.name_tag
  }
}

resource "aws_kms_key" "benchmark" {
  description             = "Customer-managed KMS key for the benchmark S3 bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = local.common_tags
}

resource "aws_s3_bucket" "benchmark" {
  bucket        = var.bucket_name
  force_destroy = var.force_destroy

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "benchmark" {
  bucket = aws_s3_bucket.benchmark.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.benchmark.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "benchmark" {
  bucket = aws_s3_bucket.benchmark.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_account_public_access_block" "account" {
  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

variable "bucket_base_name" {
  description = "Base name used to construct the CloudTrail log bucket name."
  type        = string
  default     = "benchmark"
}

locals {
  bucket_name = "${var.bucket_base_name}-cloudtrail-${data.aws_region.current.name}"
  account_id  = data.aws_caller_identity.current.account_id
  partition   = data.aws_partition.current.partition
  account_arn = "arn:${local.partition}:iam::${local.account_id}:root"
}

resource "aws_kms_key" "cloudtrail" {
  description             = "Customer-managed KMS key for CloudTrail log encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountPermissions"
        Effect = "Allow"
        Principal = {
          AWS = local.account_arn
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudTrailEncrypt"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "cloudtrail" {
  name          = "alias/${local.bucket_name}"
  target_key_id = aws_kms_key.cloudtrail.key_id
}

resource "aws_s3_bucket" "cloudtrail" {
  bucket        = local.bucket_name
  force_destroy = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.cloudtrail.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_policy" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AWSCloudTrailAclCheck"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "s3:GetBucketAcl"
        Resource = aws_s3_bucket.cloudtrail.arn
      },
      {
        Sid    = "AWSCloudTrailWrite"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.cloudtrail.arn}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })
}

variable "app_name" {
  description = "Human-readable application name used for tagging."
  type        = string
  default     = "Trilium Notes"
}

variable "app" {
  description = "Short application identifier used when building resource names."
  type        = string
  default     = "trilium"
}

variable "module" {
  description = "Module (component) identifier used when building resource names."
  type        = string
  default     = "log"
}

variable "stage" {
  description = "Deployment stage/environment used when building resource names."
  type        = string
  default     = "production"
}

variable "log_retention" {
  description = "Number of days to retain logs in the CloudWatch log groups."
  type        = number
  default     = 120
}

locals {
  app_log_group_name   = "cwlg-${var.app}-${var.module}-${var.stage}-app"
  proxy_log_group_name = "cwlg-${var.app}-${var.module}-${var.stage}-proxy"

  default_tags = {
    App    = var.app_name
    Module = var.module
    Stage  = var.stage
  }
}

resource "aws_cloudwatch_log_group" "app" {
  name              = local.app_log_group_name
  retention_in_days = var.log_retention

  tags = merge(local.default_tags, {
    Name = local.app_log_group_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cloudwatch_log_group" "proxy" {
  name              = local.proxy_log_group_name
  retention_in_days = var.log_retention

  tags = merge(local.default_tags, {
    Name = local.proxy_log_group_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

locals {
  efs_creation_token = "cloudrail-test"
  task_family        = "cloudrail-test-encryption"
  efs_volume_name    = "service-storage"
  efs_root_directory = "/opt/data"
  efs_transit_port   = 2999
}

resource "aws_efs_file_system" "this" {
  creation_token = local.efs_creation_token
  encrypted      = true

  tags = {
    Name = local.efs_creation_token
  }
}

resource "aws_ecs_task_definition" "this" {
  family                   = local.task_family
  network_mode             = "bridge"
  requires_compatibilities = ["EC2"]

  tags = {
    Name = local.task_family
  }

  container_definitions = jsonencode([
    {
      name      = "first"
      image     = "service-first"
      cpu       = 10
      memory    = 512
      essential = true
      portMappings = [
        {
          hostPort      = 80
          containerPort = 80
        }
      ]
      mountPoints = [
        {
          sourceVolume  = local.efs_volume_name
          containerPath = local.efs_root_directory
          readOnly      = false
        }
      ]
    },
    {
      name      = "second"
      image     = "service-second"
      cpu       = 10
      memory    = 256
      essential = true
      portMappings = [
        {
          hostPort      = 443
          containerPort = 443
        }
      ]
      mountPoints = [
        {
          sourceVolume  = local.efs_volume_name
          containerPath = local.efs_root_directory
          readOnly      = false
        }
      ]
    }
  ])

  volume {
    name = local.efs_volume_name

    efs_volume_configuration {
      file_system_id          = aws_efs_file_system.this.id
      root_directory          = local.efs_root_directory
      transit_encryption      = "ENABLED"
      transit_encryption_port = local.efs_transit_port
    }
  }
}

locals {
  repository_name_prefix = "saints-xctf-api"

  common_tags = {
    Application = "saints-xctf"
    Environment = "all"
  }
}

resource "aws_ecr_repository" "flask" {
  name                 = "${local.repository_name_prefix}-flask"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.repository_name_prefix}-flask-container-repository"
  })
}

resource "aws_ecr_repository" "nginx" {
  name                 = "${local.repository_name_prefix}-nginx"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.repository_name_prefix}-nginx-container-repository"
  })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = ">= 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

variable "key_prefix" {
  description = "Prefix used when constructing the AWS key pair name."
  type        = string
  default     = "key"
}

# Two-word random pet name identifier appended to the key prefix.
resource "random_pet" "this" {
  length    = 2
  separator = "-"
}

locals {
  key_name         = "${var.key_prefix}-${random_pet.this.id}"
  private_key_path = "../${local.key_name}.pem"
}

# Dynamically generated 4096-bit RSA private key that backs the AWS key pair.
resource "tls_private_key" "this" {
  algorithm = "RSA"
  rsa_bits  = 4096

  lifecycle {
    prevent_destroy = true
  }
}

# SSH access key pair whose name is derived from key_prefix plus the random pet name.
resource "aws_key_pair" "this" {
  key_name   = local.key_name
  public_key = tls_private_key.this.public_key_openssh

  # Persist the private key in PEM format to the parent directory and lock it down to 600.
  provisioner "local-exec" {
    command = "echo '${tls_private_key.this.private_key_pem}' > ${local.private_key_path} && chmod 600 ${local.private_key_path}"
  }
}

locals {
  vpc_cidr_block      = "10.0.0.0/16"
  security_group_name = "Example security group"
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "example-vpc"
  }
}

resource "aws_security_group" "web" {
  name        = local.security_group_name
  description = "Allow inbound web traffic on ports 443 and 80"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = local.security_group_name
  }
}

resource "aws_vpc_security_group_ingress_rule" "https" {
  security_group_id = aws_security_group.web.id
  description       = "Allow inbound HTTPS traffic on port 443"
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"

  tags = {
    Name = "allow-https"
  }
}

resource "aws_vpc_security_group_ingress_rule" "http" {
  security_group_id = aws_security_group.web.id
  description       = "Allow inbound HTTP traffic on port 80"
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 80
  to_port           = 80
  ip_protocol       = "tcp"

  tags = {
    Name = "allow-http"
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

locals {
  vpc_cidr    = "10.0.0.0/16"
  subnet_cidr = "10.0.1.0/24"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "example"
  }
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.subnet_cidr
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "example"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "example"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "example"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "example" {
  name        = "example"
  description = "Example security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow inbound SSH from within the VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "Allow outbound traffic within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "example"
  }
}

variable "repository_name" {
  description = "Name of the Amazon ECR repository used for development container images."
  type        = string
  default     = "illumidesk"
}

variable "image_tag_mutability" {
  description = "Tag mutability setting for the ECR repository."
  type        = string
  default     = "IMMUTABLE"
}

variable "scan_on_push" {
  description = "Whether images are scanned for vulnerabilities when pushed to the repository."
  type        = bool
  default     = true
}

variable "tags" {
  description = "Map of tags to apply to the ECR repository."
  type        = map(string)
  default = {
    Name        = "illumidesk-eks"
    Environment = "dev"
  }
}

locals {
  # Retain untagged images for 14 days after they are pushed, then expire them.
  lifecycle_policy = {
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images older than 14 days since they were pushed."
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = 14
        }
        action = {
          type = "expire"
        }
      },
      {
        rulePriority = 2
        description  = "Expire images when the total image count exceeds 30 for any tag status."
        selection = {
          tagStatus   = "any"
          countType   = "imageCountMoreThan"
          countNumber = 30
        }
        action = {
          type = "expire"
        }
      },
    ]
  }
}

resource "aws_ecr_repository" "this" {
  name                 = var.repository_name
  image_tag_mutability = var.image_tag_mutability

  image_scanning_configuration {
    scan_on_push = var.scan_on_push
  }

  encryption_configuration {
    encryption_type = "AES256"
  }

  tags = var.tags
}

resource "aws_ecr_lifecycle_policy" "this" {
  repository = aws_ecr_repository.this.name

  policy = jsonencode(local.lifecycle_policy)
}

variable "aws_region" {
  description = "AWS region stored in the authentication credentials payload."
  type        = string
  default     = "us-east-1"
}

variable "user_pool_name" {
  description = "Name of the Cognito User Pool."
  type        = string
  default     = "tech-lanches-clientes-pool"
}

variable "user_pool_client_name" {
  description = "Name of the Cognito User Pool Client."
  type        = string
  default     = "pool-client"
}

variable "secret_name" {
  description = "Name of the Secrets Manager secret holding the auth credentials."
  type        = string
  default     = "lambda-auth-credentials"
}

variable "default_username" {
  description = "Default username stored in the auth credentials payload."
  type        = string
  default     = "techlanches"
}

variable "default_email" {
  description = "Default email stored in the auth credentials payload."
  type        = string
  default     = "g12.4soat.fiap@outlook.com"
}

variable "default_password" {
  description = "Default password stored in the auth credentials payload."
  type        = string
  sensitive   = true
  default     = "Test1234@"
}

locals {
  user_pool_tags = {
    Name = "tech_lanches_clientes_pool"
  }
}

resource "aws_cognito_user_pool" "clientes" {
  name = var.user_pool_name

  mfa_configuration = "OFF"

  username_configuration {
    case_sensitive = false
  }

  auto_verified_attributes = ["email"]

  alias_attributes = ["email", "preferred_username"]

  tags = local.user_pool_tags
}

resource "aws_cognito_user_pool_client" "pool_client" {
  name         = var.user_pool_client_name
  user_pool_id = aws_cognito_user_pool.clientes.id

  explicit_auth_flows = [
    "ALLOW_REFRESH_TOKEN_AUTH",
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_ADMIN_USER_PASSWORD_AUTH",
  ]
}

resource "aws_secretsmanager_secret" "auth_credentials" {
  name                    = var.secret_name
  recovery_window_in_days = 0

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "auth_credentials" {
  secret_id = aws_secretsmanager_secret.auth_credentials.id

  secret_string = jsonencode({
    region       = var.aws_region
    userPoolId   = aws_cognito_user_pool.clientes.id
    clientId     = aws_cognito_user_pool_client.pool_client.id
    username     = var.default_username
    email        = var.default_email
    password     = var.default_password
  })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.80.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region in which the networking stack is deployed."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block assigned to the main VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "availability_zones" {
  description = "Availability zones used for subnet placement. Defaults to the first two AZs of the region when left empty."
  type        = list(string)
  default     = []
}

variable "subnet_cidrs" {
  description = "CIDR blocks assigned to each subnet, in order."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

locals {
  subnet_count = length(var.subnet_cidrs)
  selected_azs = length(var.availability_zones) > 0 ? var.availability_zones : slice(data.aws_availability_zones.available.names, 0, local.subnet_count)
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "main" {
  count = local.subnet_count

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidrs[count.index]
  availability_zone = local.selected_azs[count.index]

  tags = {
    Name = "main-subnet-${count.index + 1}"
  }
}

output "vpc_id" {
  description = "ID of the created main VPC."
  value       = aws_vpc.main.id
}

output "subnet_ids" {
  description = "IDs of the created subnets."
  value       = aws_subnet.main[*].id
}

output "subnet_availability_zones" {
  description = "Availability zones of the created subnets."
  value       = aws_subnet.main[*].availability_zone
}

locals {
  api_name        = "HelloWorldAPI"
  api_description = "API Gateway for Hello World Lambda"
  hello_path_part = "hello"
}

resource "aws_api_gateway_rest_api" "hello_world" {
  name        = local.api_name
  description = local.api_description
}

resource "aws_api_gateway_resource" "hello" {
  rest_api_id = aws_api_gateway_rest_api.hello_world.id
  parent_id   = aws_api_gateway_rest_api.hello_world.root_resource_id
  path_part   = local.hello_path_part
}

resource "aws_api_gateway_method" "hello_any" {
  rest_api_id   = aws_api_gateway_rest_api.hello_world.id
  resource_id   = aws_api_gateway_resource.hello.id
  http_method   = "ANY"
  authorization = "NONE"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  queue_name_primary   = "test-sqs"
  queue_name_secondary = "test-sqs1"
  environment          = "production"

  queue_delay_seconds           = 90
  queue_max_message_size        = 2048
  queue_message_retention       = 86400
  queue_receive_wait_time       = 10
  queue_kms_data_key_reuse_time = 300

  common_tags = {
    Environment = local.environment
  }
}

resource "aws_kms_key" "sqs" {
  description             = "Customer-managed KMS key for encrypting ${local.queue_name_primary} and ${local.queue_name_secondary} SQS queues"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableIAMUserPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowSQSEncryption"
        Effect = "Allow"
        Principal = {
          Service = "sqs.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sqs_queue" "test_sqs" {
  name                              = local.queue_name_primary
  delay_seconds                     = local.queue_delay_seconds
  max_message_size                  = local.queue_max_message_size
  message_retention_seconds         = local.queue_message_retention
  receive_wait_time_seconds         = local.queue_receive_wait_time
  kms_master_key_id                 = aws_kms_key.sqs.id
  kms_data_key_reuse_period_seconds = local.queue_kms_data_key_reuse_time

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sqs_queue" "test_sqs1" {
  name                              = local.queue_name_secondary
  delay_seconds                     = local.queue_delay_seconds
  max_message_size                  = local.queue_max_message_size
  message_retention_seconds         = local.queue_message_retention
  receive_wait_time_seconds         = local.queue_receive_wait_time
  kms_master_key_id                 = aws_kms_key.sqs.id
  kms_data_key_reuse_period_seconds = local.queue_kms_data_key_reuse_time

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which the resources are created."
  type        = string
  default     = "us-east-1"
}

variable "base_bucket_name" {
  description = "Base name used to construct the S3 bucket name."
  type        = string
  default     = "doc-io-files"
}

variable "force_destroy" {
  description = "Whether the S3 bucket may be destroyed even when it still contains objects."
  type        = bool
  default     = true
}

variable "account_id" {
  description = "AWS account ID that is granted full S3 access to the bucket."
  type        = string
  default     = "566373416292"
}

###############################################################################
# Data sources
###############################################################################

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  # Dynamically constructed bucket name: random integer prefix + base name.
  bucket_name = "${random_integer.bucket_suffix.result}-${var.base_bucket_name}"

  tags = {
    Name = local.bucket_name
  }
}

###############################################################################
# Random suffix
###############################################################################

resource "random_integer" "bucket_suffix" {
  min = 1
  max = 50000
}

###############################################################################
# KMS key for default bucket encryption (customer-managed)
###############################################################################

resource "aws_kms_key" "this" {
  description             = "Customer-managed KMS key for encrypting objects in ${local.bucket_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# S3 bucket
###############################################################################

resource "aws_s3_bucket" "this" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this.arn
    }

    bucket_key_enabled = true
  }
}

###############################################################################
# Bucket policy - full S3 access for the specified account
###############################################################################

data "aws_iam_policy_document" "bucket" {
  statement {
    sid    = "AllowAccountFullS3Access"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${var.account_id}:root"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*",
    ]
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.bucket.json
}

locals {
  bucket_prefix = "terraform-remote-state"
  table_name    = "terraform-lock"
  kms_alias     = "alias/terraform-remote-state"
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

# ---------------------------------------------------------------------------
# KMS key used to encrypt the state bucket and the lock table
# ---------------------------------------------------------------------------
resource "aws_kms_key" "state" {
  description             = "KMS key for Terraform remote state encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = local.kms_alias
  }
}

resource "aws_kms_alias" "state" {
  name          = local.kms_alias
  target_key_id = aws_kms_key.state.key_id
}

# ---------------------------------------------------------------------------
# S3 bucket holding the Terraform remote state
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "state" {
  bucket_prefix = local.bucket_prefix

  tags = {
    Name = local.bucket_prefix
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.state.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

# ---------------------------------------------------------------------------
# DynamoDB table used for state locking
# ---------------------------------------------------------------------------
resource "aws_dynamodb_table" "lock" {
  name         = local.table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.state.arn
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = {
    Name = local.table_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  topic_name = "incident-response"
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
}

# ---------------------------------------------------------------------------
# Dedicated customer-managed KMS key used to encrypt the SNS topic.
# Automatic key rotation is enabled.
# ---------------------------------------------------------------------------
resource "aws_kms_key" "incident_response" {
  description             = "Customer managed KMS key for encrypting the ${local.topic_name} SNS topic"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "${local.topic_name}-kms-key-policy"
    Statement = [
      {
        Sid    = "EnableRootAccountAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowSNSAndEventBridgeToUseKey"
        Effect = "Allow"
        Principal = {
          Service = [
            "sns.amazonaws.com",
            "events.amazonaws.com"
          ]
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "incident_response" {
  name          = "alias/${local.topic_name}"
  target_key_id = aws_kms_key.incident_response.key_id
}

# ---------------------------------------------------------------------------
# SNS topic used for operational incident notifications.
# ---------------------------------------------------------------------------
resource "aws_sns_topic" "incident_response" {
  name              = local.topic_name
  kms_master_key_id = aws_kms_key.incident_response.id
}

# ---------------------------------------------------------------------------
# Topic policy with the default policy ID and two permission statements.
# ---------------------------------------------------------------------------
resource "aws_sns_topic_policy" "incident_response" {
  arn = aws_sns_topic.incident_response.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "__default_policy_ID"
    Statement = [
      {
        Sid    = "__default_statement_ID"
        Effect = "Allow"
        Principal = {
          AWS = "*"
        }
        Action = [
          "SNS:Subscribe",
          "SNS:SetTopicAttributes",
          "SNS:RemovePermission",
          "SNS:Receive",
          "SNS:Publish",
          "SNS:ListSubscriptionsByTopic",
          "SNS:GetTopicAttributes",
          "SNS:DeleteTopic",
          "SNS:AddPermission"
        ]
        Resource = aws_sns_topic.incident_response.arn
        Condition = {
          StringEquals = {
            "AWS:SourceOwner" = local.account_id
          }
        }
      },
      {
        Sid    = "AllowAWSEvents"
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Action   = "SNS:Publish"
        Resource = aws_sns_topic.incident_response.arn
      }
    ]
  })
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

###############################################################################
# Static provider/account metadata (pure lookups, no pre-existing infra)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Local values
###############################################################################

locals {
  # Service principal used by both the service-linked role and the log policy.
  opensearch_service_principal = "es.amazonaws.com"

  # Exact name requested for the CloudWatch Logs resource policy.
  log_resource_policy_name = "elasticsearch-log-publishing-policy"

  # ARN pattern scoping the policy to the OpenSearch/Elasticsearch log groups
  # that the service publishes into CloudWatch Logs.
  opensearch_log_group_arn_pattern = "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:log-group:/aws/opensearch/*"
}

###############################################################################
# IAM service-linked role for Amazon OpenSearch/Elasticsearch (es.amazonaws.com)
#
# The Amazon Elasticsearch/OpenSearch service-linked role for es.amazonaws.com
# is a singleton that AWS provisions automatically and that does not support
# custom suffixes. It is therefore adopted via an import so it can be managed
# declaratively without attempting to recreate the singleton.
###############################################################################

import {
  to = aws_iam_service_linked_role.opensearch
  id = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:role/aws-service-role/${local.opensearch_service_principal}/AWSServiceRoleForAmazonElasticsearchService"
}

resource "aws_iam_service_linked_role" "opensearch" {
  aws_service_name = local.opensearch_service_principal
  description      = "Service-linked role for Amazon OpenSearch/Elasticsearch Service used to publish logs to CloudWatch Logs"
}

###############################################################################
# CloudWatch Logs resource policy that allows the Elasticsearch service
# principal to publish logs.
###############################################################################

resource "aws_cloudwatch_log_resource_policy" "elasticsearch" {
  policy_name = local.log_resource_policy_name

  policy_document = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ElasticsearchLogPublishing"
        Effect = "Allow"
        Principal = {
          Service = local.opensearch_service_principal
        }
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:PutLogEventsBatch"
        ]
        Resource = [
          local.opensearch_log_group_arn_pattern
        ]
      }
    ]
  })
}

locals {
  user_pool_name  = "identity pool"
  role_name       = "user-group-role"
  group_name      = "user-group"
  group_desc      = "Managed by Terraform"
  group_precedence = 42

  identity_pool_id = "us-east-1:12345678-dead-beef-cafe-123456790ab"

  assume_role_policy = {
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = local.identity_pool_id
          }
          "ForAnyValue:StringLike" = {
            "cognito-identity.amazonaws.com:amr" = "authenticated"
          }
        }
      }
    ]
  }
}

resource "aws_cognito_user_pool" "identity_pool" {
  name = local.user_pool_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "user_group_role" {
  name               = local.role_name
  assume_role_policy = jsonencode(local.assume_role_policy)

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cognito_user_group" "user_group" {
  name        = local.group_name
  user_pool_id = aws_cognito_user_pool.identity_pool.id
  description = local.group_desc
  precedence  = local.group_precedence
  role_arn    = aws_iam_role.user_group_role.arn

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

# Alternate AWS provider alias used to manage the second DynamoDB table.
# The first table is managed by the standard (default) AWS provider.
provider "aws" {
  alias = "alt-tags"
}

locals {
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "KeyId"

  basic_table_name     = "default-and-alternate-tags-module-basic"
  alternate_table_name = "default-and-alternate-tags-module-alternate"
}

# Table managed by the standard AWS provider.
resource "aws_dynamodb_table" "basic" {
  name         = local.basic_table_name
  billing_mode = local.billing_mode
  hash_key     = local.hash_key

  attribute {
    name = local.hash_key
    type = "S"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Table managed by the alternate "alt-tags" AWS provider alias.
resource "aws_dynamodb_table" "alternate" {
  provider = aws.alt-tags

  name         = local.alternate_table_name
  billing_mode = local.billing_mode
  hash_key     = local.hash_key

  attribute {
    name = local.hash_key
    type = "S"
  }

  lifecycle {
    prevent_destroy = true
  }
}

variable "api_name" {
  description = "Name of the API Gateway REST API"
  type        = string
  default     = "terraform-api-gateway-example"
}

locals {
  movies_path_part = "movies"
  http_method_get  = "GET"
  status_code_200  = "200"

  mock_request_template = jsonencode({
    statusCode = 200
  })

  mock_response_template = jsonencode({
    message = "Hello from the movies API!"
  })
}

resource "aws_api_gateway_rest_api" "this" {
  name        = var.api_name
  description = "Mock REST API for testing web endpoint responses"

  endpoint_configuration {
    types = ["REGIONAL"]
  }
}

resource "aws_api_gateway_resource" "movies" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  parent_id   = aws_api_gateway_rest_api.this.root_resource_id
  path_part   = local.movies_path_part
}

resource "aws_api_gateway_method" "movies_get" {
  rest_api_id   = aws_api_gateway_rest_api.this.id
  resource_id   = aws_api_gateway_resource.movies.id
  http_method   = local.http_method_get
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "movies_get_mock" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  resource_id = aws_api_gateway_resource.movies.id
  http_method = aws_api_gateway_method.movies_get.http_method
  type        = "MOCK"

  request_templates = {
    "application/json" = local.mock_request_template
  }
}

resource "aws_api_gateway_method_response" "movies_get_200" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  resource_id = aws_api_gateway_resource.movies.id
  http_method = aws_api_gateway_method.movies_get.http_method
  status_code = local.status_code_200

  response_models = {
    "application/json" = "Empty"
  }
}

resource "aws_api_gateway_integration_response" "movies_get_200" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  resource_id = aws_api_gateway_resource.movies.id
  http_method = aws_api_gateway_method.movies_get.http_method
  status_code = aws_api_gateway_method_response.movies_get_200.status_code

  response_templates = {
    "application/json" = local.mock_response_template
  }

  depends_on = [aws_api_gateway_integration.movies_get_mock]
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "kms_alias_prefix" {
  description = "Prefix applied to the KMS alias name. KMS aliases must start with 'alias/'."
  type        = string
  default     = "alias/"
}

variable "kms_alias_name" {
  description = "Default KMS alias identifier used to build the full alias name."
  type        = string
  default     = "kms-cmk-example"
}

variable "kms_key_description" {
  description = "Description for the KMS customer managed key."
  type        = string
  default     = "KMS CMK example key for testing"
}

variable "kms_deletion_window_in_days" {
  description = "Number of days before the KMS key is permanently deleted (7-30)."
  type        = number
  default     = 7
}

variable "tags" {
  description = "Common tags applied to all resources."
  type        = map(string)
  default = {
    Purpose = "kms-cmk-example"
    Managed = "terraform"
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  kms_alias_full_name = "${var.kms_alias_prefix}${var.kms_alias_name}"

  common_tags = merge(var.tags, {
    Name = var.kms_alias_name
  })
}

###############################################################################
# Data sources (static provider / identity metadata only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

###############################################################################
# KMS Customer Managed Key (CMK)
###############################################################################

resource "aws_kms_key" "this" {
  description             = var.kms_key_description
  deletion_window_in_days = var.kms_deletion_window_in_days
  enable_key_rotation     = true

  tags = local.common_tags
}

###############################################################################
# Key policy: full KMS permissions ("kms:*") exclusively to the caller identity
###############################################################################

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "AllowCallerIdentityFullKMSAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [data.aws_caller_identity.current.arn]
    }

    actions = ["kms:*"]

    resources = [aws_kms_key.this.arn]
  }
}

resource "aws_kms_key_policy" "this" {
  key_id = aws_kms_key.this.id
  policy = data.aws_iam_policy_document.kms_key_policy.json
}

###############################################################################
# KMS Alias targeting the created key
###############################################################################

resource "aws_kms_alias" "this" {
  name          = local.kms_alias_full_name
  target_key_id = aws_kms_key.this.key_id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  alias  = "us-east-nv"
  region = "us-east-1"

  default_tags {
    tags = {
      Terraform = "yes"
      Region    = "N.Virginia"
    }
  }
}

provider "aws" {
  alias  = "ap-south-mumbai"
  region = "ap-south-1"

  default_tags {
    tags = {
      Terraform = "yes"
      Region    = "Mumbai"
    }
  }
}

resource "aws_vpc" "north_virginia" {
  provider   = aws.us-east-nv
  cidr_block = "10.1.0.0/16"

  tags = {
    Name = "North-Virginia-VPC"
  }
}

resource "aws_vpc" "mumbai" {
  provider   = aws.ap-south-mumbai
  cidr_block = "10.2.0.0/16"

  tags = {
    Name = "Mumbai-VPC"
  }
}

locals {
  vpc_cidr = "10.0.0.0/16"
  vpc_name = "outbound-traffic-evaluation-vpc"
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = local.vpc_name
  }
}

resource "aws_security_group" "allow_tcp" {
  name        = "allow_tcp"
  description = "Allow TCP traffic"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow TCP traffic"
    from_port   = 10000
    to_port     = 10000
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "allow_tcp"
  }
}

resource "aws_security_group" "allow_udp" {
  name        = "allow_udp"
  description = "Allow UDP traffic"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow UDP traffic"
    from_port   = 10000
    to_port     = 10000
    protocol    = "udp"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "allow_udp"
  }
}

resource "aws_security_group" "allow_icmp" {
  name        = "allow_icmp"
  description = "Allow ICMP traffic"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow ICMP traffic"
    from_port   = -1
    to_port     = -1
    protocol    = "icmp"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "allow_icmp"
  }
}

resource "aws_security_group" "allow_all" {
  name        = "allow_all"
  description = "Allow ALL traffic"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow ALL traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "allow_all"
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.99.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  # Globally unique, deterministic bucket name derived from the current
  # account and region so no hardcoded IDs are required.
  state_bucket_name = "terraform-state-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"

  lock_table_name = "terraform-lock"

  tags = {
    Name        = "terraform-state-backend"
    ManagedBy   = "Terraform"
    Environment = "shared"
  }
}

# ---------------------------------------------------------------------------
# Dedicated customer-managed KMS key for state encryption
# ---------------------------------------------------------------------------

resource "aws_kms_key" "state" {
  description             = "Customer-managed KMS key for Terraform state backend encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  tags                    = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "state" {
  name          = "alias/terraform-state"
  target_key_id = aws_kms_key.state.key_id
}

# ---------------------------------------------------------------------------
# S3 bucket for remote Terraform state
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "state" {
  bucket = local.state_bucket_name
  tags   = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.state.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------
# DynamoDB table for state locking
# ---------------------------------------------------------------------------

resource "aws_dynamodb_table" "lock" {
  name         = local.lock_table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"
  tags         = local.tags

  attribute {
    name = "LockID"
    type = "S"
  }

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

variable "regions" {
  description = "List of AWS regions in which the PowerScale node runtime may assign private IP addresses to network interfaces."
  type        = list(string)
  default     = ["*"]
}

locals {
  account_id  = data.aws_caller_identity.current.account_id
  partition   = data.aws_partition.current.partition
  name_prefix = "${local.account_id}-powerscale-node-runtime"
  policy_name = "${local.name_prefix}-policy"
  role_name   = "${local.name_prefix}-role"
  profile_name = "${local.name_prefix}-instance-profile"

  network_interface_arns = [
    for region in var.regions :
    "arn:${local.partition}:ec2:${region}:${local.account_id}:network-interface/*"
  ]
}

data "aws_iam_policy_document" "node_runtime" {
  statement {
    sid    = "AssignPrivateIpAddresses"
    effect = "Allow"

    actions = [
      "ec2:AssignPrivateIpAddresses",
    ]

    resources = local.network_interface_arns
  }
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "AllowEc2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_policy" "node_runtime" {
  name        = local.policy_name
  description = "Allows PowerScale node runtime operations to assign private IP addresses to EC2 network interfaces."
  policy      = data.aws_iam_policy_document.node_runtime.json
}

resource "aws_iam_role" "node_runtime" {
  name        = local.role_name
  description = "Execution role for PowerScale node runtime operations on EC2 instances."

  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
}

resource "aws_iam_role_policy_attachment" "node_runtime" {
  role       = aws_iam_role.node_runtime.name
  policy_arn = aws_iam_policy.node_runtime.arn
}

resource "aws_iam_instance_profile" "node_runtime" {
  name = local.profile_name
  role = aws_iam_role.node_runtime.name
}

output "policy_name" {
  description = "Name of the PowerScale node runtime IAM policy."
  value       = aws_iam_policy.node_runtime.name
}

output "role_name" {
  description = "Name of the PowerScale node runtime IAM role."
  value       = aws_iam_role.node_runtime.name
}

output "instance_profile_name" {
  description = "Name of the PowerScale node runtime IAM instance profile."
  value       = aws_iam_instance_profile.node_runtime.name
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_cidr = "192.168.0.0/16"

  subnets = {
    web = {
      cidr_block        = "192.168.0.0/24"
      availability_zone = data.aws_availability_zones.available.names[0]
      tier              = "web"
    }
    app = {
      cidr_block        = "192.168.1.0/24"
      availability_zone = data.aws_availability_zones.available.names[1]
      tier              = "app"
    }
    db = {
      cidr_block        = "192.168.2.0/24"
      availability_zone = data.aws_availability_zones.available.names[2]
      tier              = "db"
    }
    mgmt = {
      cidr_block        = "192.168.3.0/24"
      availability_zone = data.aws_availability_zones.available.names[0]
      tier              = "mgmt"
    }
  }
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "tiered-app-vpc"
  }
}

resource "aws_subnet" "tiered" {
  for_each = local.subnets

  vpc_id            = aws_vpc.main.id
  cidr_block        = each.value.cidr_block
  availability_zone = each.value.availability_zone

  tags = {
    Name = each.value.tier
    Tier = each.value.tier
  }
}

###############################################################################
# Variables
###############################################################################

variable "role_name" {
  description = "Name of the IAM role created for EC2 instances (also used to derive the instance profile name)."
  type        = string
  default     = "ec2-instance-role"
}

variable "role_description" {
  description = "Description of the IAM role created for EC2 instances."
  type        = string
  default     = "IAM role that allows EC2 instances to assume it and use attached policies."
}

variable "role_path" {
  description = "Path under which the IAM role and instance profile are created."
  type        = string
  default     = "/"
}

variable "managed_policy_arns" {
  description = "Set of managed IAM policy ARNs to attach to the role (AWS managed and/or customer managed)."
  type        = set(string)
  default     = []
}

variable "inline_policies" {
  description = "Map of inline policy names to JSON-encoded IAM policy documents to attach to the role."
  type        = map(string)
  default     = {}
}

variable "max_session_duration" {
  description = "Maximum session duration (in seconds) for the role. Between 3600 and 43200."
  type        = number
  default     = 3600

  validation {
    condition     = var.max_session_duration >= 3600 && var.max_session_duration <= 43200
    error_message = "max_session_duration must be between 3600 and 43200 seconds."
  }
}

variable "permissions_boundary_arn" {
  description = "Optional ARN of a permissions boundary policy to apply to the role."
  type        = string
  default     = null
}

variable "tags" {
  description = "Tags to apply to the created resources."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  instance_profile_name = var.role_name
}

###############################################################################
# Data Sources
###############################################################################

# Partition metadata (e.g. aws, aws-cn, aws-us-gov) used to build the
# partition-specific EC2 service principal.
data "aws_partition" "current" {}

###############################################################################
# IAM Role
###############################################################################

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "AllowEC2InstancesToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.${data.aws_partition.current.dns_suffix}"]
    }
  }
}

resource "aws_iam_role" "this" {
  name                 = var.role_name
  description          = var.role_description
  path                 = var.role_path
  assume_role_policy   = data.aws_iam_policy_document.ec2_assume_role.json
  max_session_duration = var.max_session_duration

  permissions_boundary = var.permissions_boundary_arn

  tags = var.tags
}

###############################################################################
# Instance Profile
###############################################################################

resource "aws_iam_instance_profile" "this" {
  name = local.instance_profile_name
  path = var.role_path
  role = aws_iam_role.this.name

  tags = var.tags
}

###############################################################################
# Managed Policy Attachments (configurable set)
###############################################################################

resource "aws_iam_role_policy_attachment" "managed" {
  for_each = var.managed_policy_arns

  role       = aws_iam_role.this.name
  policy_arn = each.value
}

###############################################################################
# Inline Policies (configurable set)
###############################################################################

resource "aws_iam_role_policy" "inline" {
  for_each = var.inline_policies

  name   = each.key
  role   = aws_iam_role.this.id
  policy = each.value
}

###############################################################################
# Outputs
###############################################################################

output "role_name" {
  description = "Name of the created IAM role."
  value       = aws_iam_role.this.name
}

output "role_arn" {
  description = "ARN of the created IAM role."
  value       = aws_iam_role.this.arn
}

output "instance_profile_name" {
  description = "Name of the created IAM instance profile."
  value       = aws_iam_instance_profile.this.name
}

output "instance_profile_arn" {
  description = "ARN of the created IAM instance profile."
  value       = aws_iam_instance_profile.this.arn
}

output "ec2_service_principal" {
  description = "Partition-specific EC2 service principal allowed to assume the role."
  value       = "ec2.${data.aws_partition.current.dns_suffix}"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  cluster_name = "Fast-App"
  vpc_cidr     = "10.0.0.0/16"

  # Spread the network across the first three available AZs in the region.
  azs = slice(data.aws_availability_zones.available.names, 0, 3)

  # /24 public and private tiers carved out of the VPC CIDR.
  public_subnet_cidrs  = [for i, _ in local.azs : cidrsubnet(local.vpc_cidr, 8, i)]
  private_subnet_cidrs = [for i, _ in local.azs : cidrsubnet(local.vpc_cidr, 8, i + 100)]

  common_tags = {
    Cluster   = local.cluster_name
    ManagedBy = "Terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-vpc"
  })
}

# Public subnet tier (one per AZ) — routable to the internet gateway.
resource "aws_subnet" "public" {
  count = length(local.azs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-public-${local.azs[count.index]}"
    Tier = "public"
  })
}

# Private subnet tier (one per AZ) — isolated from the internet gateway.
resource "aws_subnet" "private" {
  count = length(local.azs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-private-${local.azs[count.index]}"
    Tier = "private"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-igw"
  })
}

# Public route table with a default route to the internet gateway.
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-public-rt"
    Tier = "public"
  })
}

resource "aws_route" "public_internet_access" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count = length(local.azs)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_cidr = "10.0.0.0/16"

  private_subnets = {
    private_a = {
      cidr = "10.0.1.0/24"
      az   = data.aws_availability_zones.available.names[0]
    }
    private_b = {
      cidr = "10.0.2.0/24"
      az   = data.aws_availability_zones.available.names[1]
    }
  }
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "test-network-vpc"
  }
}

resource "aws_subnet" "private" {
  for_each = local.private_subnets

  vpc_id            = aws_vpc.main.id
  cidr_block        = each.value.cidr
  availability_zone = each.value.az

  tags = {
    Name = "test-network-${each.key}"
    Tier = "Private"
  }
}

output "vpc_id" {
  description = "The ID of the VPC."
  value       = aws_vpc.main.id
}

output "private_subnet_ids" {
  description = "Aggregated list of private subnet IDs."
  value       = [for s in aws_subnet.private : s.id]
}

output "private_subnet_cidrs" {
  description = "Aggregated list of private subnet CIDR blocks."
  value       = [for s in aws_subnet.private : s.cidr_block]
}

output "private_subnet_1_id" {
  description = "The ID of the first private subnet."
  value       = aws_subnet.private["private_a"].id
}

output "private_subnet_2_id" {
  description = "The ID of the second private subnet."
  value       = aws_subnet.private["private_b"].id
}

output "private_subnet_1_cidr" {
  description = "The CIDR block of the first private subnet."
  value       = aws_subnet.private["private_a"].cidr_block
}

output "private_subnet_2_cidr" {
  description = "The CIDR block of the second private subnet."
  value       = aws_subnet.private["private_b"].cidr_block
}

output "public_subnet_ids" {
  description = "Aggregated list of public subnet IDs (mirrors the private subnets)."
  value       = [for s in aws_subnet.private : s.id]
}

output "public_subnet_cidrs" {
  description = "Aggregated list of public subnet CIDR blocks (mirrors the private subnets)."
  value       = [for s in aws_subnet.private : s.cidr_block]
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_name             = "trade-tariff-development-vpc"
  vpc_cidr             = "10.0.0.0/16"
  public_subnet_cidrs  = ["10.0.1.0/24", "10.0.2.0/24"]
  private_subnet_cidrs = ["10.0.11.0/24", "10.0.12.0/24"]

  common_tags = {
    Name        = local.vpc_name
    Environment = "development"
    ManagedBy   = "Terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = local.vpc_name
  })
}

resource "aws_subnet" "public" {
  count             = length(local.public_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-public-${data.aws_availability_zones.available.names[count.index]}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count             = length(local.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-private-${data.aws_availability_zones.available.names[count.index]}"
    Tier = "private"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-igw"
  })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-nat"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  count  = length(local.private_subnet_cidrs)
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-private-rt-${count.index + 1}"
  })
}

resource "aws_route_table_association" "private" {
  count          = length(aws_subnet.private)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_security_group" "allow_ssh" {
  name        = "allow-ssh"
  description = "Allow inbound SSH and outbound traffic only within the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "allow-ssh"
  })
}

resource "aws_vpc_security_group_ingress_rule" "ssh" {
  security_group_id = aws_security_group.allow_ssh.id
  description       = "Allow inbound SSH from within the VPC CIDR"
  cidr_ipv4         = aws_vpc.main.cidr_block
  from_port         = 22
  to_port           = 22
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_egress_rule" "vpc_only" {
  security_group_id = aws_security_group.allow_ssh.id
  description       = "Allow all outbound traffic only within the VPC CIDR"
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "-1"
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source = "hashicorp/aws"
    }
  }
}

###############################################################################
# Static provider metadata (safe, non-stateful lookups)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Variables
###############################################################################

variable "repository_name" {
  description = "Name of the ECR repository."
  type        = string
  default     = "app-images"

  validation {
    condition     = can(regex("^[a-z0-9]+([._/-][a-z0-9]+)*$", var.repository_name))
    error_message = "Repository name must be lowercase and may contain digits, dots, dashes, underscores and slashes."
  }
}

variable "image_tag_mutability" {
  description = "Tag mutability setting for the repository (MUTABLE or IMMUTABLE)."
  type        = string
  default     = "IMMUTABLE"

  validation {
    condition     = contains(["MUTABLE", "IMMUTABLE"], var.image_tag_mutability)
    error_message = "image_tag_mutability must be either MUTABLE or IMMUTABLE."
  }
}

variable "image_scan_on_push" {
  description = "Whether images are scanned for vulnerabilities when pushed."
  type        = bool
  default     = true
}

variable "enable_kms_encryption" {
  description = "When true, the repository is encrypted with a customer-managed KMS key. When false, AES256 (default ECR encryption) is used."
  type        = bool
  default     = false
}

variable "kms_key_deletion_window_in_days" {
  description = "Waiting period, in days, before the customer-managed KMS key is deleted."
  type        = number
  default     = 30

  validation {
    condition     = var.kms_key_deletion_window_in_days >= 7 && var.kms_key_deletion_window_in_days <= 30
    error_message = "kms_key_deletion_window_in_days must be between 7 and 30."
  }
}

variable "allowed_pull_principals" {
  description = "List of AWS principal ARNs allowed to pull images. When empty, no repository access policy is created."
  type        = list(string)
  default     = []
}

variable "enable_lifecycle_policy" {
  description = "When true, a lifecycle policy is attached to the repository for image cleanup."
  type        = bool
  default     = false
}

variable "untagged_image_expiry_days" {
  description = "Number of days after which untagged images are expired."
  type        = number
  default     = 14
}

variable "max_tagged_images" {
  description = "Maximum number of tagged images to retain."
  type        = number
  default     = 30
}

###############################################################################
# Locals
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  create_repository_policy = length(var.allowed_pull_principals) > 0
}

###############################################################################
# Customer-managed KMS key (only when explicitly enabled)
###############################################################################

resource "aws_kms_key" "ecr" {
  count = var.enable_kms_encryption ? 1 : 0

  description             = "Customer-managed key for ECR repository ${var.repository_name}."
  deletion_window_in_days = var.kms_key_deletion_window_in_days
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "ecr" {
  count = var.enable_kms_encryption ? 1 : 0

  name          = "alias/${var.repository_name}-ecr"
  target_key_id = aws_kms_key.ecr[0].key_id
}

###############################################################################
# ECR repository
###############################################################################

resource "aws_ecr_repository" "this" {
  name                 = var.repository_name
  image_tag_mutability = var.image_tag_mutability
  force_delete         = true

  image_scanning_configuration {
    scan_on_push = var.image_scan_on_push
  }

  # When KMS encryption is enabled, use a customer-managed key.
  # Otherwise, omit the block so ECR uses its AES256 default.
  dynamic "encryption_configuration" {
    for_each = var.enable_kms_encryption ? [1] : []

    content {
      encryption_type = "KMS"
      kms_key         = aws_kms_key.ecr[0].arn
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Optional repository access policy (pull-only, least privilege)
###############################################################################

resource "aws_ecr_repository_policy" "this" {
  count = local.create_repository_policy ? 1 : 0

  repository = aws_ecr_repository.this.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowPullAccess"
        Effect = "Allow"
        Principal = {
          AWS = var.allowed_pull_principals
        }
        Action = [
          "ecr:BatchCheckLayerAvailability",
          "ecr:BatchGetImage",
          "ecr:GetDownloadUrlForLayer"
        ]
      }
    ]
  })
}

###############################################################################
# Optional lifecycle policy for image cleanup
###############################################################################

resource "aws_ecr_lifecycle_policy" "this" {
  count = var.enable_lifecycle_policy ? 1 : 0

  repository = aws_ecr_repository.this.name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images older than ${var.untagged_image_expiry_days} days."
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = var.untagged_image_expiry_days
        }
        action = {
          type = "expire"
        }
      },
      {
        rulePriority = 2
        description  = "Retain only the most recent ${var.max_tagged_images} tagged images."
        selection = {
          tagStatus      = "tagged"
          tagPatternList = ["*"]
          countType      = "imageCountMoreThan"
          countNumber    = var.max_tagged_images
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

###############################################################################
# Outputs
###############################################################################

output "repository_name" {
  description = "Name of the ECR repository."
  value       = aws_ecr_repository.this.name
}

output "repository_url" {
  description = "URL of the ECR repository."
  value       = aws_ecr_repository.this.repository_url
}

output "repository_arn" {
  description = "ARN of the ECR repository."
  value       = aws_ecr_repository.this.arn
}

output "encryption_type" {
  description = "Encryption type used by the repository."
  value       = var.enable_kms_encryption ? "KMS" : "AES256"
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key, if enabled."
  value       = var.enable_kms_encryption ? aws_kms_key.ecr[0].arn : null
}

###############################################################################
# Standard Naming & Tagging conventions
#
# A reusable naming/tagging contract is provided via the `name`, `environment`
# and `tags` inputs.  The derived queue name and the merged tag set are exposed
# through `locals` so every resource in this configuration (and any consumer of
# the outputs) shares one consistent, canonical naming + tagging scheme.
###############################################################################

variable "name" {
  description = "Base name for the queue. Combined with `environment` to build the final queue name."
  type        = string
  default     = "app"
}

variable "environment" {
  description = "Deployment environment (e.g. dev, staging, prod) used for naming and tagging."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags to merge onto every resource created by this configuration."
  type        = map(string)
  default     = {}
}

###############################################################################
# Queue configuration
###############################################################################

variable "fifo_queue" {
  description = "Whether to create a FIFO queue. When true the queue name is suffixed with '.fifo'."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enable content-based deduplication (only meaningful for FIFO queues)."
  type        = bool
  default     = false
}

variable "deduplication_scope" {
  description = "Specifies whether message deduplication occurs at the message group (messageGroup) or queue (queue) level. Only valid for FIFO queues."
  type        = string
  default     = null

  validation {
    condition     = var.deduplication_scope == null || contains(["messageGroup", "queue"], coalesce(var.deduplication_scope, "queue"))
    error_message = "deduplication_scope must be either \"messageGroup\" or \"queue\"."
  }
}

variable "fifo_throughput_limit" {
  description = "Specifies whether the FIFO queue throughput quota applies to the entire queue (perQueue) or per message group id (perMessageGroupId). Only valid for FIFO queues."
  type        = string
  default     = null

  validation {
    condition     = var.fifo_throughput_limit == null || contains(["perQueue", "perMessageGroupId"], coalesce(var.fifo_throughput_limit, "perQueue"))
    error_message = "fifo_throughput_limit must be either \"perQueue\" or \"perMessageGroupId\"."
  }
}

variable "delay_seconds" {
  description = "Seconds for which the delivery of all messages in the queue is delayed."
  type        = number
  default     = 0
}

variable "max_message_size" {
  description = "Maximum message size in bytes (1024 to 262144)."
  type        = number
  default     = 262144
}

variable "message_retention_seconds" {
  description = "Number of seconds Amazon SQS retains a message (60 to 1209600)."
  type        = number
  default     = 345600
}

variable "receive_wait_time_seconds" {
  description = "Long-polling wait time in seconds (0 to 20)."
  type        = number
  default     = 0
}

variable "visibility_timeout_seconds" {
  description = "Visibility timeout for the queue in seconds (0 to 43200)."
  type        = number
  default     = 30
}

variable "sqs_managed_sse_enabled" {
  description = "Enable SQS-managed server-side encryption (SSE-SQS) for the queue."
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "Optional KMS key ID/alias/ARN for SSE-KMS encryption. When set, SSE-KMS is used instead of SSE-SQS."
  type        = string
  default     = null
}

variable "kms_data_key_reuse_period_seconds" {
  description = "Length of time, in seconds, for which Amazon SQS can reuse a data key to encrypt/decrypt messages before calling AWS KMS again."
  type        = number
  default     = null
}

###############################################################################
# Optional access policy
###############################################################################

variable "allowed_principal_arn" {
  description = "AWS principal (account ID, IAM user/role ARN) granted sqs:SendMessage on the queue. Leave empty to skip policy creation."
  type        = string
  default     = ""
}

###############################################################################
# Locals: canonical naming + tagging
###############################################################################

locals {
  # FIFO queues must have a name ending in '.fifo'.
  base_queue_name = "${var.name}-${var.environment}"
  queue_name      = var.fifo_queue ? "${local.base_queue_name}.fifo" : local.base_queue_name

  common_tags = merge(
    {
      Name        = local.queue_name
      Environment = var.environment
      ManagedBy   = "Terraform"
    },
    var.tags,
  )

  create_queue_policy = var.allowed_principal_arn != ""
}

###############################################################################
# SQS Queue
###############################################################################

resource "aws_sqs_queue" "this" {
  name = local.queue_name

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : false
  deduplication_scope         = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null

  delay_seconds              = var.delay_seconds
  max_message_size           = var.max_message_size
  message_retention_seconds  = var.message_retention_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds
  visibility_timeout_seconds = var.visibility_timeout_seconds

  # Server-side encryption. When a KMS key is supplied SSE-KMS is used,
  # otherwise the queue relies on SQS-managed encryption (SSE-SQS).
  sqs_managed_sse_enabled           = var.kms_master_key_id == null ? var.sqs_managed_sse_enabled : null
  kms_master_key_id                 = var.kms_master_key_id
  kms_data_key_reuse_period_seconds = var.kms_master_key_id == null ? null : var.kms_data_key_reuse_period_seconds

  tags = local.common_tags
}

###############################################################################
# Optional queue access policy granting a specified principal SendMessage
###############################################################################

data "aws_iam_policy_document" "send_message" {
  count = local.create_queue_policy ? 1 : 0

  statement {
    sid    = "AllowSpecifiedPrincipalSendMessage"
    effect = "Allow"

    actions   = ["sqs:SendMessage"]
    resources = [aws_sqs_queue.this.arn]

    principals {
      type        = "AWS"
      identifiers = [var.allowed_principal_arn]
    }
  }
}

resource "aws_sqs_queue_policy" "this" {
  count = local.create_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.this.id
  policy    = data.aws_iam_policy_document.send_message[0].json
}

###############################################################################
# Outputs
###############################################################################

output "queue_name" {
  description = "Name of the SQS queue."
  value       = aws_sqs_queue.this.name
}

output "queue_arn" {
  description = "ARN of the SQS queue."
  value       = aws_sqs_queue.this.arn
}

output "queue_url" {
  description = "URL of the SQS queue."
  value       = aws_sqs_queue.this.id
}

output "queue_tags" {
  description = "The canonical tag set applied to the queue."
  value       = local.common_tags
}

###############################################################################
# Input variables
###############################################################################

variable "create" {
  description = "Whether to create the Aurora DSQL cluster and its optional peering relationships."
  type        = bool
  default     = true
}

variable "name" {
  description = "Name used to identify the DSQL cluster (applied as the Name tag)."
  type        = string
  default     = "dsql-cluster"
}

variable "region" {
  description = "AWS region the cluster is deployed in (used for tagging)."
  type        = string
  default     = "us-east-1"
}

variable "tags" {
  description = "A map of tags to assign to the DSQL cluster."
  type        = map(string)
  default     = {}
}

variable "deletion_protection_enabled" {
  description = "Whether deletion protection is enabled on the DSQL cluster."
  type        = bool
  default     = true
}

variable "force_destroy" {
  description = "Whether to destroy the cluster even when deletion protection is enabled."
  type        = bool
  default     = false
}

variable "kms_encryption_key" {
  description = "ARN of the AWS KMS key that encrypts data in the cluster, or AWS_OWNED_KMS_KEY."
  type        = string
  default     = null
}

variable "cluster_create_timeout" {
  description = "Timeout for the DSQL cluster create operation."
  type        = string
  default     = "30m"
}

variable "enable_multi_region" {
  description = "Whether to configure the DSQL cluster as a multi-region cluster."
  type        = bool
  default     = false
}

variable "multi_region_witness_region" {
  description = "Witness region used when the DSQL cluster is multi-region."
  type        = string
  default     = null
}

variable "enable_cluster_peering" {
  description = "Whether to create cluster peering relationships to other DSQL clusters."
  type        = bool
  default     = false
}

variable "peer_cluster_identifiers" {
  description = "ARNs of the DSQL clusters to peer with."
  type        = list(string)
  default     = []
}

variable "peering_witness_region" {
  description = "Witness region used for the cluster peering relationship."
  type        = string
  default     = null
}

variable "peering_create_timeout" {
  description = "Timeout for the cluster peering create operation."
  type        = string
  default     = "30m"
}

###############################################################################
# Locals
###############################################################################

locals {
  create_cluster = var.create

  common_tags = merge(
    var.tags,
    {
      Name   = var.name
      Region = var.region
    },
  )

  # Peering is only ever provisioned when explicitly enabled and a non-empty
  # list of peer cluster ARNs is supplied.
  peer_cluster_arns = var.create && var.enable_cluster_peering ? var.peer_cluster_identifiers : []
}

###############################################################################
# Aurora DSQL cluster
###############################################################################

resource "aws_dsql_cluster" "this" {
  count = local.create_cluster ? 1 : 0

  deletion_protection_enabled = var.deletion_protection_enabled
  force_destroy               = var.force_destroy
  kms_encryption_key          = var.kms_encryption_key

  dynamic "multi_region_properties" {
    for_each = var.enable_multi_region ? [1] : []

    content {
      witness_region = var.multi_region_witness_region
    }
  }

  tags = local.common_tags

  timeouts {
    create = var.cluster_create_timeout
  }
}

###############################################################################
# Optional cluster peering relationship(s)
###############################################################################

resource "aws_dsql_cluster_peering" "this" {
  count = length(local.peer_cluster_arns) > 0 ? 1 : 0

  identifier     = aws_dsql_cluster.this[0].identifier
  clusters       = local.peer_cluster_arns
  witness_region = var.peering_witness_region

  timeouts {
    create = var.peering_create_timeout
  }
}

###############################################################################
# Outputs
###############################################################################

output "cluster_arn" {
  description = "ARN of the DSQL cluster."
  value       = try(aws_dsql_cluster.this[0].arn, null)
}

output "cluster_identifier" {
  description = "Identifier of the DSQL cluster."
  value       = try(aws_dsql_cluster.this[0].identifier, null)
}

output "cluster_kms_encryption_key" {
  description = "KMS encryption key used by the DSQL cluster."
  value       = try(aws_dsql_cluster.this[0].kms_encryption_key, null)
}

output "cluster_encryption_details" {
  description = "Encryption configuration details of the DSQL cluster."
  value       = try(aws_dsql_cluster.this[0].encryption_details, null)
}

output "cluster_multi_region_properties" {
  description = "Multi-region properties of the DSQL cluster."
  value       = try(aws_dsql_cluster.this[0].multi_region_properties, null)
}

output "cluster_vpc_endpoint_service_name" {
  description = "VPC endpoint service name associated with the DSQL cluster."
  value       = try(aws_dsql_cluster.this[0].vpc_endpoint_service_name, null)
}

output "cluster_peering_clusters" {
  description = "ARNs of the peer DSQL clusters configured for peering, if created."
  value       = local.peer_cluster_arns
}

###############################################################################
# Variables
###############################################################################

variable "bucket_name" {
  description = "Explicit, globally unique name of the S3 bucket to create. When null, a unique name is generated from bucket_name_prefix."
  type        = string
  default     = null
}

variable "bucket_name_prefix" {
  description = "Prefix used to generate a globally unique bucket name when bucket_name is not provided."
  type        = string
  default     = "customizable-bucket-"
}

variable "object_lock_enabled" {
  description = "Whether S3 Object Lock is enabled for the bucket."
  type        = bool
  default     = false
}

variable "force_destroy" {
  description = "Whether all objects are deleted from the bucket when the bucket is destroyed. Defaults to false to prevent accidental deletion of non-empty buckets."
  type        = bool
  default     = false
}

variable "tags" {
  description = "A map of tags to apply to all resources created by this configuration."
  type        = map(string)
  default     = {}
}

variable "bucket_policies" {
  description = "Map of custom bucket policies keyed by a unique policy identifier. Each entry declares a policy version and a list of statements supporting an optional SID, one or more actions, an effect (defaults to Allow), a list of resources, and a list of principals."
  type = map(object({
    version = optional(string, "2012-10-17")
    statements = list(object({
      sid       = optional(string, "")
      effect    = optional(string, "Allow")
      actions   = list(string)
      resources = list(string)
      principals = optional(list(object({
        type        = string
        identifiers = list(string)
      })), [])
    }))
  }))
  default = {}

  validation {
    condition = alltrue(flatten([
      for policy in values(var.bucket_policies) : [
        for statement in policy.statements : contains(["Allow", "Deny"], statement.effect)
      ]
    ]))
    error_message = "Every bucket policy statement effect must be either \"Allow\" or \"Deny\"."
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  common_tags = merge(
    {
      ManagedBy = "Terraform"
    },
    var.tags,
  )

  # Build one JSON policy document per entry in var.bucket_policies. The map key
  # acts as the policy identifier. When var.bucket_policies is empty this map is
  # empty and no bucket policy resources are created.
  bucket_policy_documents = {
    for policy_id, policy in var.bucket_policies : policy_id => jsonencode({
      Version = policy.version
      Statement = [
        for statement in policy.statements : merge(
          {
            Effect   = statement.effect
            Action   = statement.actions
            Resource = statement.resources
          },
          statement.sid != "" ? { Sid = statement.sid } : {},
          length(statement.principals) > 0 ? {
            Principal = {
              for principal in statement.principals : principal.type => principal.identifiers
            }
          } : {},
        )
      ]
    })
  }
}

###############################################################################
# KMS Key (dedicated customer managed key for bucket default encryption)
#
# No custom key policy is declared so the AWS default key policy applies. The
# default policy grants the account full KMS administration, which is required
# for operations such as key rotation and for S3 to use the key for encryption.
###############################################################################

resource "aws_kms_key" "s3" {
  description             = "Customer managed KMS key for default encryption of the S3 bucket managed by this configuration"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "s3" {
  name          = "alias/${aws_s3_bucket.this.bucket}-s3"
  target_key_id = aws_kms_key.s3.key_id
}

###############################################################################
# S3 Bucket
###############################################################################

resource "aws_s3_bucket" "this" {
  bucket        = var.bucket_name
  bucket_prefix = var.bucket_name == null ? var.bucket_name_prefix : null

  object_lock_enabled = var.object_lock_enabled
  force_destroy       = var.force_destroy

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode = "GOVERNANCE"
      days = 1
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

###############################################################################
# Optional Bucket Policies
###############################################################################

resource "aws_s3_bucket_policy" "this" {
  for_each = local.bucket_policy_documents

  bucket = aws_s3_bucket.this.id
  policy = each.value

  depends_on = [aws_s3_bucket_public_access_block.this]
}

###############################################################################
# Amazon SNS Topic module
#
# Creates a versatile SNS topic supporting:
#   - Conditional creation of every resource via a single `create` toggle
#   - Explicit name or generated name prefix
#   - Display name, FIFO + content-based deduplication, KMS master key
#   - Protocol specific delivery status feedback IAM roles
#   - A managed IAM topic policy with a default owner-access statement plus
#     source / override / user-defined statements
#   - Dynamically generated topic subscriptions
###############################################################################

###############################################################################
# Provider metadata (static lookups only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

###############################################################################
# Variables
###############################################################################

variable "create" {
  description = "Determines whether the SNS topic and all related resources are created"
  type        = bool
  default     = true
}

variable "name" {
  description = "The name of the SNS topic. Conflicts with `name_prefix`."
  type        = string
  default     = null
}

variable "name_prefix" {
  description = "Creates a unique name beginning with the specified prefix. Conflicts with `name`."
  type        = string
  default     = "sns-topic-"
}

variable "display_name" {
  description = "The human-readable string used as the display name for the topic"
  type        = string
  default     = null
}

variable "fifo_topic" {
  description = "Boolean indicating whether or not to create a FIFO (first-in-first-out) topic"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication for FIFO topics"
  type        = bool
  default     = false
}

variable "kms_master_key_id" {
  description = "The ID of an AWS-managed or customer managed master key (CMK) used to encrypt messages on the topic"
  type        = string
  default     = null
}

variable "signature_version" {
  description = "The signature version used when creating the signature of the notifications/confirmations sent by Amazon SNS"
  type        = number
  default     = null
}

variable "tracing_config" {
  description = "Tracing mode of an Amazon SNS topic. Valid values: `PassThrough`, `Active`."
  type        = string
  default     = null

  validation {
    condition     = var.tracing_config == null || contains(["PassThrough", "Active"], coalesce(var.tracing_config, "PassThrough"))
    error_message = "The tracing_config value must be either 'PassThrough' or 'Active'."
  }
}

variable "delivery_policy" {
  description = "The SNS delivery policy as JSON"
  type        = string
  default     = null
}

variable "delivery_status_feedback_sample_rate" {
  description = "The percentage of successful/failed delivery status feedback to be sampled (0-100)"
  type        = number
  default     = 100

  validation {
    condition     = var.delivery_status_feedback_sample_rate >= 0 && var.delivery_status_feedback_sample_rate <= 100
    error_message = "The delivery_status_feedback_sample_rate value must be between 0 and 100."
  }
}

variable "feedback_role_protocols" {
  description = "Set of endpoint protocols for which delivery status feedback IAM roles are created"
  type        = set(string)
  default     = ["application", "firehose", "http", "lambda", "sqs"]

  validation {
    condition = alltrue([
      for p in var.feedback_role_protocols : contains(["application", "firehose", "http", "lambda", "sqs"], p)
    ])
    error_message = "feedback_role_protocols must only contain: application, firehose, http, lambda, sqs."
  }
}

variable "enable_default_topic_policy" {
  description = "Determines whether to attach the default (owner access) topic policy, merged with any supplied policy documents"
  type        = bool
  default     = true
}

variable "source_topic_policy_documents" {
  description = "List of IAM policy documents that are merged together into the topic policy (source documents, lower precedence)"
  type        = list(string)
  default     = []
}

variable "override_topic_policy_documents" {
  description = "List of IAM policy documents that are merged together into the topic policy (override documents, higher precedence)"
  type        = list(string)
  default     = []
}

variable "topic_policy_statements" {
  description = "List of additional statements to add to the topic policy"
  type = list(object({
    sid       = optional(string)
    effect    = optional(string, "Allow")
    actions   = list(string)
    resources = list(string)
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })), [])
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })), [])
  }))
  default = []
}

variable "subscriptions" {
  description = "A map of subscriptions to create on the SNS topic"
  type = map(object({
    protocol                        = string
    endpoint                        = string
    endpoint_auto_confirms          = optional(bool, false)
    confirmation_timeout_in_minutes = optional(number, 1)
    raw_message_delivery            = optional(bool, false)
    filter_policy                   = optional(string, null)
    filter_policy_scope             = optional(string, null)
    delivery_policy                 = optional(string, null)
    redrive_policy                  = optional(string, null)
    replay_policy                   = optional(string, null)
    subscription_role_arn           = optional(string, null)
  }))
  default = {}

  validation {
    condition = alltrue([
      for s in values(var.subscriptions) : contains([
        "application", "firehose", "http", "https", "email",
        "email-json", "lambda", "sms", "sqs"
      ], s.protocol)
    ])
    error_message = "Subscription protocol must be one of: application, firehose, http, https, email, email-json, lambda, sms, sqs."
  }
}

variable "tags" {
  description = "A map of tags to assign to the resources"
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  create = var.create

  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  # An explicit name wins over the generated name prefix
  name = var.name != null && trimspace(var.name) != "" ? var.name : null

  # Protocols for which delivery status feedback roles should exist
  feedback_protocols = local.create ? var.feedback_role_protocols : toset([])

  # Map of protocol => feedback role ARN (empty when the role was not created)
  feedback_role_arns = { for k, v in aws_iam_role.feedback : k => v.arn }

  # CloudWatch Logs log group ARNs written to by SNS delivery status feedback
  feedback_log_group_arn        = "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:sns/*"
  feedback_log_group_stream_arn = "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:sns/*:*"
}

###############################################################################
# Delivery status feedback IAM roles
###############################################################################

data "aws_iam_policy_document" "sns_assume_role" {
  count = length(local.feedback_protocols) > 0 ? 1 : 0

  statement {
    sid     = "AllowSNSServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "feedback" {
  count = length(local.feedback_protocols) > 0 ? 1 : 0

  statement {
    sid    = "SNSDeliveryStatusLogging"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:PutMetricFilter",
      "logs:PutRetentionPolicy",
    ]
    resources = [
      local.feedback_log_group_arn,
      local.feedback_log_group_stream_arn,
    ]
  }
}

resource "aws_iam_role" "feedback" {
  for_each = local.feedback_protocols

  name_prefix        = "sns-${each.key}-feedback-"
  assume_role_policy = data.aws_iam_policy_document.sns_assume_role[0].json

  tags = var.tags
}

resource "aws_iam_role_policy" "feedback" {
  for_each = local.feedback_protocols

  name   = "sns-delivery-status-feedback"
  role   = aws_iam_role.feedback[each.key].id
  policy = data.aws_iam_policy_document.feedback[0].json
}

###############################################################################
# SNS topic
###############################################################################

resource "aws_sns_topic" "this" {
  count = local.create ? 1 : 0

  name         = local.name
  name_prefix  = local.name == null ? var.name_prefix : null
  display_name = var.display_name

  delivery_policy = var.delivery_policy

  signature_version = var.signature_version
  tracing_config    = var.tracing_config

  fifo_topic                  = var.fifo_topic
  content_based_deduplication = var.fifo_topic ? var.content_based_deduplication : null

  kms_master_key_id = var.kms_master_key_id

  # Delivery status feedback roles (created above when enabled)
  application_success_feedback_role_arn    = lookup(local.feedback_role_arns, "application", null)
  application_success_feedback_sample_rate = lookup(local.feedback_role_arns, "application", null) != null ? var.delivery_status_feedback_sample_rate : null
  application_failure_feedback_role_arn    = lookup(local.feedback_role_arns, "application", null)

  firehose_success_feedback_role_arn    = lookup(local.feedback_role_arns, "firehose", null)
  firehose_success_feedback_sample_rate = lookup(local.feedback_role_arns, "firehose", null) != null ? var.delivery_status_feedback_sample_rate : null
  firehose_failure_feedback_role_arn    = lookup(local.feedback_role_arns, "firehose", null)

  http_success_feedback_role_arn    = lookup(local.feedback_role_arns, "http", null)
  http_success_feedback_sample_rate = lookup(local.feedback_role_arns, "http", null) != null ? var.delivery_status_feedback_sample_rate : null
  http_failure_feedback_role_arn    = lookup(local.feedback_role_arns, "http", null)

  lambda_success_feedback_role_arn    = lookup(local.feedback_role_arns, "lambda", null)
  lambda_success_feedback_sample_rate = lookup(local.feedback_role_arns, "lambda", null) != null ? var.delivery_status_feedback_sample_rate : null
  lambda_failure_feedback_role_arn    = lookup(local.feedback_role_arns, "lambda", null)

  sqs_success_feedback_role_arn    = lookup(local.feedback_role_arns, "sqs", null)
  sqs_success_feedback_sample_rate = lookup(local.feedback_role_arns, "sqs", null) != null ? var.delivery_status_feedback_sample_rate : null
  sqs_failure_feedback_role_arn    = lookup(local.feedback_role_arns, "sqs", null)

  tags = var.tags
}

###############################################################################
# Managed topic policy (owner access + custom / source / override statements)
###############################################################################

data "aws_iam_policy_document" "this" {
  count = local.create && var.enable_default_topic_policy ? 1 : 0

  source_policy_documents   = var.source_topic_policy_documents
  override_policy_documents = var.override_topic_policy_documents

  dynamic "statement" {
    for_each = var.topic_policy_statements

    content {
      sid    = try(statement.value.sid, null)
      effect = statement.value.effect

      actions   = statement.value.actions
      resources = statement.value.resources

      dynamic "principals" {
        for_each = statement.value.principals

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = statement.value.conditions

        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }

  statement {
    sid    = "TopicOwnerAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions = [
      "SNS:GetTopicAttributes",
      "SNS:SetTopicAttributes",
      "SNS:AddPermission",
      "SNS:RemovePermission",
      "SNS:DeleteTopic",
      "SNS:Subscribe",
      "SNS:ListSubscriptionsByTopic",
      "SNS:Publish",
    ]

    resources = [aws_sns_topic.this[0].arn]
  }
}

resource "aws_sns_topic_policy" "this" {
  count = local.create && var.enable_default_topic_policy ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = data.aws_iam_policy_document.this[0].json
}

###############################################################################
# Topic subscriptions
###############################################################################

resource "aws_sns_topic_subscription" "this" {
  for_each = local.create ? var.subscriptions : {}

  topic_arn = aws_sns_topic.this[0].arn

  protocol                        = each.value.protocol
  endpoint                        = each.value.endpoint
  endpoint_auto_confirms          = each.value.endpoint_auto_confirms
  confirmation_timeout_in_minutes = each.value.confirmation_timeout_in_minutes
  raw_message_delivery            = each.value.raw_message_delivery
  filter_policy                   = each.value.filter_policy
  filter_policy_scope             = each.value.filter_policy_scope
  delivery_policy                 = each.value.delivery_policy
  redrive_policy                  = each.value.redrive_policy
  replay_policy                   = each.value.replay_policy
  subscription_role_arn           = each.value.subscription_role_arn
}

###############################################################################
# Outputs
###############################################################################

output "topic_arn" {
  description = "The ARN of the SNS topic"
  value       = try(aws_sns_topic.this[0].arn, null)
}

output "topic_id" {
  description = "The ID of the SNS topic"
  value       = try(aws_sns_topic.this[0].id, null)
}

output "topic_name" {
  description = "The name of the SNS topic"
  value       = try(aws_sns_topic.this[0].name, null)
}

output "topic_owner" {
  description = "The AWS account ID of the SNS topic owner"
  value       = try(aws_sns_topic.this[0].owner, null)
}

output "topic_policy" {
  description = "The JSON of the managed topic policy"
  value       = try(aws_sns_topic_policy.this[0].policy, null)
}

output "feedback_role_arns" {
  description = "Map of protocol => delivery status feedback IAM role ARN"
  value       = local.feedback_role_arns
}

output "subscription_arns" {
  description = "Map of subscription key => subscription ARN"
  value       = { for k, v in aws_sns_topic_subscription.this : k => v.arn }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_name             = "ansible-vpc"
  vpc_cidr             = "10.0.0.0/16"
  private_subnet_name  = "ansible-vpc-private-subnet-1"
  private_subnet_cidr  = "10.0.0.0/24"
  public_subnet_name   = "ansible-vpc-public-subnet-1"
  public_subnet_cidr   = "10.0.1.0/24"
  internet_gateway_name = "ansible-vpc-igw"
  public_route_table_name  = "ansible-vpc-public-rt"
  private_route_table_name = "ansible-vpc-private-rt"
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = local.vpc_name
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidr
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = local.private_subnet_name
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = local.public_subnet_name
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = local.internet_gateway_name
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = local.public_route_table_name
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = local.private_route_table_name
  }
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Centralized inter-VPC routing via an AWS Transit Gateway
#
# This configuration creates a Transit Gateway and attaches one or more VPCs
# to it. Each VPC is defined in the `vpc_definitions` map; the subnets created
# for each VPC are used as the Transit Gateway attachment subnets. All traffic
# between the VPCs is centralized through a single Transit Gateway route table.
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

###############################################################################
# Variables
###############################################################################

variable "vpc_definitions" {
  description = "Map of VPCs to create and attach to the Transit Gateway, keyed by a logical VPC name. Each VPC declares its CIDR block and the CIDR blocks of its attachment subnets."
  type = map(object({
    cidr_block         = string
    subnet_cidr_blocks = list(string)
  }))

  default = {
    vpc_a = {
      cidr_block         = "10.10.0.0/16"
      subnet_cidr_blocks = ["10.10.1.0/24"]
    }
    vpc_b = {
      cidr_block         = "10.20.0.0/16"
      subnet_cidr_blocks = ["10.20.1.0/24"]
    }
  }
}

variable "transit_gateway_asn" {
  description = "Amazon-side BGP ASN for the Transit Gateway."
  type        = number
  default     = 64512
}

variable "flow_log_retention_days" {
  description = "Retention period in days for VPC flow log CloudWatch log group."
  type        = number
  default     = 365
}

###############################################################################
# Locals
###############################################################################

locals {
  tags = {
    Project   = "centralized-transit-gateway"
    ManagedBy = "terraform"
  }

  az_names = sort(data.aws_availability_zones.available.names)

  # Flattened map of every subnet to create, keyed by "<vpc>-<index>".
  subnets = merge([
    for vpc_key, vpc in var.vpc_definitions : {
      for idx, cidr in vpc.subnet_cidr_blocks :
      "${vpc_key}-${idx}" => {
        vpc_key    = vpc_key
        cidr_block = cidr
        az         = local.az_names[idx % length(local.az_names)]
      }
    }
  ]...)

  # Map of subnet IDs per VPC, used as the Transit Gateway attachment subnets.
  tgw_vpc_attachments = {
    for vpc_key, vpc in var.vpc_definitions : vpc_key => {
      vpc_id     = aws_vpc.this[vpc_key].id
      subnet_ids = [for idx, _ in vpc.subnet_cidr_blocks : aws_subnet.this["${vpc_key}-${idx}"].id]
    }
  }

  # Routes from every VPC route table to every *other* VPC CIDR via the TGW.
  inter_vpc_routes = merge([
    for src_key, src in var.vpc_definitions : {
      for dst_key, dst in var.vpc_definitions :
      "${src_key}-to-${dst_key}" => {
        route_table_key        = src_key
        destination_cidr_block = dst.cidr_block
      } if src_key != dst_key
    }
  ]...)
}

###############################################################################
# VPCs and subnets
###############################################################################

resource "aws_vpc" "this" {
  for_each = var.vpc_definitions

  cidr_block           = each.value.cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, {
    Name = each.key
  })
}

resource "aws_subnet" "this" {
  for_each = local.subnets

  vpc_id                  = aws_vpc.this[each.value.vpc_key].id
  cidr_block              = each.value.cidr_block
  availability_zone       = each.value.az
  map_public_ip_on_launch = false

  tags = merge(local.tags, {
    Name = each.key
  })
}

# Lock down the VPC default security group (no inbound/outbound rules).
resource "aws_default_security_group" "this" {
  for_each = aws_vpc.this

  vpc_id = each.value.id

  tags = merge(local.tags, {
    Name = "${each.key}-default-sg"
  })
}

###############################################################################
# VPC flow logs (CloudWatch + KMS)
###############################################################################

resource "aws_kms_key" "flow_log" {
  description             = "KMS key used to encrypt VPC flow logs"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogs"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.region}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:Describe*"
        ]
        Resource = "*"
      }
    ]
  })

  tags = local.tags
}

resource "aws_cloudwatch_log_group" "flow_log" {
  name_prefix       = "/aws/vpc/flow-logs-"
  retention_in_days = var.flow_log_retention_days
  kms_key_id        = aws_kms_key.flow_log.arn

  tags = local.tags
}

resource "aws_iam_role" "flow_log" {
  name_prefix = "vpc-flow-log-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy" "flow_log" {
  name = "vpc-flow-log-policy"
  role = aws_iam_role.flow_log.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "${aws_cloudwatch_log_group.flow_log.arn}:*"
      }
    ]
  })
}

resource "aws_flow_log" "this" {
  for_each = aws_vpc.this

  vpc_id               = each.value.id
  traffic_type         = "ALL"
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.flow_log.arn
  iam_role_arn         = aws_iam_role.flow_log.arn

  tags = merge(local.tags, {
    Name = "${each.key}-flow-log"
  })
}

###############################################################################
# Transit Gateway
###############################################################################

resource "aws_ec2_transit_gateway" "this" {
  description                     = "Centralized inter-VPC routing transit gateway"
  amazon_side_asn                 = var.transit_gateway_asn
  auto_accept_shared_attachments  = "disable"
  default_route_table_association = "enable"
  default_route_table_propagation = "enable"
  dns_support                     = "enable"
  vpn_ecmp_support                = "enable"

  tags = merge(local.tags, {
    Name = "central-tgw"
  })
}

###############################################################################
# VPC attachments (map of subnet IDs -> Transit Gateway)
#
# Each attachment uses the Transit Gateway's default route table, which has
# association and propagation enabled. This centralizes inter-VPC routing so
# every attached VPC learns the CIDR blocks of the other attached VPCs.
###############################################################################

resource "aws_ec2_transit_gateway_vpc_attachment" "this" {
  for_each = local.tgw_vpc_attachments

  transit_gateway_id = aws_ec2_transit_gateway.this.id
  vpc_id             = each.value.vpc_id
  subnet_ids         = each.value.subnet_ids

  dns_support                                     = "enable"
  transit_gateway_default_route_table_association = true
  transit_gateway_default_route_table_propagation = true

  tags = merge(local.tags, {
    Name = "${each.key}-tgw-attachment"
  })
}

###############################################################################
# VPC route tables and inter-VPC routes through the Transit Gateway
###############################################################################

resource "aws_route_table" "this" {
  for_each = aws_vpc.this

  vpc_id = each.value.id

  tags = merge(local.tags, {
    Name = "${each.key}-rt"
  })
}

resource "aws_route" "inter_vpc" {
  for_each = local.inter_vpc_routes

  route_table_id         = aws_route_table.this[each.value.route_table_key].id
  destination_cidr_block = each.value.destination_cidr_block
  transit_gateway_id     = aws_ec2_transit_gateway.this.id

  depends_on = [aws_ec2_transit_gateway_vpc_attachment.this]
}

resource "aws_route_table_association" "this" {
  for_each = local.subnets

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.this[each.value.vpc_key].id
}

###############################################################################
# Outputs
###############################################################################

output "transit_gateway_id" {
  description = "ID of the central Transit Gateway."
  value       = aws_ec2_transit_gateway.this.id
}

output "transit_gateway_route_table_id" {
  description = "ID of the Transit Gateway default route table used for inter-VPC routing."
  value       = aws_ec2_transit_gateway.this.association_default_route_table_id
}

output "vpc_ids" {
  description = "Map of logical VPC name to VPC ID."
  value       = { for k, v in aws_vpc.this : k => v.id }
}

output "vpc_attachment_ids" {
  description = "Map of logical VPC name to Transit Gateway VPC attachment ID."
  value       = { for k, v in aws_ec2_transit_gateway_vpc_attachment.this : k => v.id }
}

output "vpc_subnet_ids" {
  description = "Map of logical VPC name to the subnet IDs used for its Transit Gateway attachment."
  value       = { for k, v in local.tgw_vpc_attachments : k => v.subnet_ids }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_cidr    = "10.0.0.0/16"
  subnet_cidr = "10.0.0.0/24"
  name_prefix = "dragondrop"

  common_tags = {
    Project   = "dragondrop"
    ManagedBy = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-rt"
  })
}

resource "aws_route" "default" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "ecs_fargate" {
  name        = "dragondrop-compute-ecs-fargate-sg"
  description = "Security group for ECS Fargate tasks; egress restricted to the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow outbound traffic within the VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "dragondrop-compute-ecs-fargate-sg"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_ecs_cluster" "main" {
  name = "${local.name_prefix}-cluster"

  setting {
    name  = "containerInsights"
    value = "enabled"
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

locals {
  raw_metrics_table_name       = "raw_metrics"
  aggregate_metrics_table_name = "aggregate_metrics"
}

# ---------------------------------------------------------------------------
# raw_metrics: raw time-series metric storage
#   - string hash key "uuid"
#   - on-demand (PAY_PER_REQUEST) billing
#   - server-side encryption
#   - DynamoDB stream with NEW_IMAGE view
#   - TTL enabled on the "expdate" attribute
# ---------------------------------------------------------------------------
resource "aws_dynamodb_table" "raw_metrics" {
  name         = local.raw_metrics_table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "uuid"

  attribute {
    name = "uuid"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  stream_enabled   = true
  stream_view_type = "NEW_IMAGE"

  ttl {
    attribute_name = "expdate"
    enabled        = true
  }

  point_in_time_recovery {
    enabled = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# aggregate_metrics: aggregated metric storage
#   - composite primary key: hash "pk" (S) + range "sk" (S)
#   - on-demand (PAY_PER_REQUEST) billing
#   - server-side encryption
#   - point-in-time recovery enabled
#   - GSI "IdentifierIndex" (hash "identifier", projection ALL)
# ---------------------------------------------------------------------------
resource "aws_dynamodb_table" "aggregate_metrics" {
  name         = local.aggregate_metrics_table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "pk"
  range_key    = "sk"

  attribute {
    name = "pk"
    type = "S"
  }

  attribute {
    name = "sk"
    type = "S"
  }

  attribute {
    name = "identifier"
    type = "S"
  }

  global_secondary_index {
    name            = "IdentifierIndex"
    hash_key        = "identifier"
    projection_type = "ALL"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Variables
###############################################################################

variable "instance_type" {
  description = "EC2 instance type for the Apache web server"
  type        = string
  default     = "t3.micro"
}

variable "server_name" {
  description = "Server name served by the Apache web server"
  type        = string
  default     = "demo"
}

###############################################################################
# Locals
###############################################################################

locals {
  vpc_cidr    = "10.0.0.0/16"
  subnet_cidr = "10.0.0.0/24"
  common_tags = {
    Project   = "apache-web-server"
    ManagedBy = "terraform"
  }
}

###############################################################################
# AMI lookup (latest Amazon Linux 2)
###############################################################################

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "state"
    values = ["available"]
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Networking
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "apache-web-server-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "apache-web-server-igw"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "apache-web-server-subnet"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "apache-web-server-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Security group
###############################################################################

resource "aws_security_group" "web" {
  name        = "apache-web-server-sg"
  description = "Allow inbound HTTP from anywhere; restrict egress to the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Egress restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "apache-web-server-sg"
  })
}

###############################################################################
# EC2 instance running Apache
###############################################################################

resource "aws_instance" "web" {
  ami                         = data.aws_ami.amazon_linux_2.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.public.id
  vpc_security_group_ids      = [aws_security_group.web.id]
  associate_public_ip_address = false

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
    instance_metadata_tags      = "enabled"
  }

  root_block_device {
    volume_type           = "gp3"
    volume_size           = 8
    encrypted             = true
    delete_on_termination = true
  }

  user_data = <<-EOF
    #!/bin/bash
    set -euo pipefail
    yum update -y
    yum install -y httpd
    systemctl enable httpd
    systemctl start httpd
    cat > /var/www/html/index.html <<HTML
    <!DOCTYPE html>
    <html>
      <head><title>${var.server_name}</title></head>
      <body><h1>${var.server_name}</h1></body>
    </html>
    HTML
  EOF

  tags = merge(local.common_tags, {
    Name = var.server_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_eip" "web" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${var.server_name}-eip"
  })
}

resource "aws_eip_association" "web" {
  instance_id   = aws_instance.web.id
  allocation_id = aws_eip.web.id
}

###############################################################################
# Outputs
###############################################################################

output "instance_id" {
  description = "ID of the Apache web server instance"
  value       = aws_instance.web.id
}

output "elastic_ip" {
  description = "Elastic IP address associated with the instance"
  value       = aws_eip.web.public_ip
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

locals {
  common_tags = {
    ManagedBy = "Terraform"
    Purpose   = "sns-messaging-integration-testing"
  }

  # Full set of SNS topic actions granted by the shared topic policy.
  sns_full_actions = [
    "SNS:AddPermission",
    "SNS:DeleteTopic",
    "SNS:GetTopicAttributes",
    "SNS:ListSubscriptionsByTopic",
    "SNS:Publish",
    "SNS:Receive",
    "SNS:RemovePermission",
    "SNS:SetTopicAttributes",
    "SNS:Subscribe",
  ]
}

# Customer-managed KMS key used to encrypt all SNS topics, with rotation enabled.
resource "aws_kms_key" "sns" {
  description             = "Customer-managed KMS key for SNS topic encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = local.common_tags
}

resource "aws_kms_alias" "sns" {
  name          = "alias/sns-messaging-integration"
  target_key_id = aws_kms_key.sns.key_id
}

# First topic that shares the topic policy allowing all AWS principals full SNS actions.
resource "aws_sns_topic" "my_topic_with_policy" {
  name              = "my-topic-with-policy"
  kms_master_key_id = aws_kms_key.sns.arn

  tags = local.common_tags
}

# Second topic that reuses the same shared topic policy document.
resource "aws_sns_topic" "my_topic_with_policy2" {
  name              = "my-topic-with-policy2"
  kms_master_key_id = aws_kms_key.sns.arn

  tags = local.common_tags
}

# Topic configured with a custom delivery policy for retry and throttling behavior.
resource "aws_sns_topic" "user_updates" {
  name              = "user-updates-topic"
  kms_master_key_id = aws_kms_key.sns.arn

  delivery_policy = jsonencode({
    http = {
      defaultHealthyRetryPolicy = {
        minDelayTarget     = 20
        maxDelayTarget     = 20
        numRetries         = 3
        numMaxDelayRetries = 0
        numNoDelayRetries  = 0
        numMinDelayRetries = 0
        backoffFunction    = "linear"
      }
      disableSubscriptionOverrides = false
      defaultThrottlePolicy = {
        maxReceivesPerSecond = 1
      }
    }
  })

  tags = local.common_tags
}

# Shared topic policy: allows all AWS principals full SNS actions on the first topic.
data "aws_iam_policy_document" "sns_topic_policy" {
  policy_id = "__default_policy_ID"

  statement {
    sid    = "__default_statement_ID"
    effect = "Allow"

    actions = local.sns_full_actions

    resources = [aws_sns_topic.my_topic_with_policy.arn]

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
  }
}

resource "aws_sns_topic_policy" "my_topic_with_policy" {
  arn    = aws_sns_topic.my_topic_with_policy.arn
  policy = data.aws_iam_policy_document.sns_topic_policy.json
}

resource "aws_sns_topic_policy" "my_topic_with_policy2" {
  arn    = aws_sns_topic.my_topic_with_policy2.arn
  policy = data.aws_iam_policy_document.sns_topic_policy.json
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_cidr            = "192.168.0.0/16"
  public_subnet_cidr  = "192.168.1.0/24"
