  cidr_block        = local.private_subnet_cidr
  availability_zone = local.availability_zone

  tags = merge(local.common_tags, {
    Name = "private-subnet"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "main-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "public-route-table"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "private-route-table"
  })
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

resource "aws_eip" "standalone" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "standalone-eip"
  })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

locals {
  name_prefix = "app"

  vpc_cidr          = "10.0.0.0/16"
  service_namespace = "service.local"

  azs                  = slice(data.aws_availability_zones.available.names, 0, 2)
  public_subnet_cidrs  = ["10.0.0.0/24", "10.0.1.0/24"]
  private_subnet_cidrs = ["10.0.10.0/24", "10.0.11.0/24"]

  common_tags = {
    Project     = local.name_prefix
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "public" {
  count = length(local.public_subnet_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-${local.azs[count.index]}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = length(local.private_subnet_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${local.azs[count.index]}"
    Tier = "private"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat-eip"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat"
  })

  depends_on = [
    aws_internet_gateway.main,
    aws_eip.nat,
  ]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-rt"
  })
}

resource "aws_route" "private_nat" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main.id
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "app" {
  name        = "${local.name_prefix}-app-sg"
  description = "Security group for containerized applications"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from within the VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "Application port 3000 from anywhere"
    from_port   = 3000
    to_port     = 3000
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "Application port 5432 from anywhere"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Outbound traffic limited to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-app-sg"
  })
}

resource "aws_service_discovery_private_dns_namespace" "main" {
  name        = local.service_namespace
  description = "Private DNS namespace for containerized application service discovery"
  vpc         = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = local.service_namespace
  })
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

locals {
  name_prefix = "benchmark-backup"
  vault_name  = "${local.name_prefix}-vault"
  plan_name   = "${local.name_prefix}-plan"
  role_name   = "${local.name_prefix}-role"

  backup_tag_key   = "benchmark-backup"
  backup_tag_value = "true"

  account_root_arn = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"

  common_tags = {
    Name      = local.name_prefix
    ManagedBy = "Terraform"
  }
}

# ---------------------------------------------------------------------------
# IAM role assumed by AWS Backup to create and manage recovery points
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    sid     = "AllowBackupServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup" {
  name               = local.role_name
  description        = "IAM role used by AWS Backup to manage recovery points"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# ---------------------------------------------------------------------------
# Customer managed KMS key used to encrypt the backup vault
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "backup_kms" {
  statement {
    sid     = "AllowAccountKeyAdministration"
    effect  = "Allow"
    actions = [
      "kms:CancelKeyDeletion",
      "kms:Create*",
      "kms:Describe*",
      "kms:Disable*",
      "kms:Enable*",
      "kms:Get*",
      "kms:List*",
      "kms:Put*",
      "kms:Revoke*",
      "kms:ScheduleKeyDeletion",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:Update*",
    ]

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    resources = ["*"]
  }

  statement {
    sid     = "AllowBackupRoleToUseKey"
    effect  = "Allow"
    actions = [
      "kms:CreateGrant",
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:ListGrants",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
      "kms:RevokeGrant",
    ]

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.backup.arn]
    }

    resources = ["*"]
  }
}

resource "aws_kms_key" "backup" {
  description             = "Customer managed key used to encrypt the AWS Backup vault"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.backup_kms.json

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-kms" })
}

resource "aws_kms_alias" "backup" {
  name          = "alias/${local.name_prefix}"
  target_key_id = aws_kms_key.backup.key_id
}

# ---------------------------------------------------------------------------
# KMS-encrypted backup vault with a vault lock enforcing retention 7-90 days
# ---------------------------------------------------------------------------
resource "aws_backup_vault" "main" {
  name        = local.vault_name
  kms_key_arn = aws_kms_key.backup.arn

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault_lock_configuration" "main" {
  backup_vault_name   = aws_backup_vault.main.name
  min_retention_days  = 7
  max_retention_days  = 90
  changeable_for_days = 3
}

# ---------------------------------------------------------------------------
# Backup plan with a scheduled rule targeting the encrypted vault
# ---------------------------------------------------------------------------
resource "aws_backup_plan" "main" {
  name = local.plan_name

  rule {
    rule_name         = "${local.name_prefix}-daily"
    target_vault_name = aws_backup_vault.main.name
    schedule          = "cron(0 5 * * ? *)"
    start_window      = 60
    completion_window = 180

    lifecycle {
      delete_after = 30
    }
  }

  tags = local.common_tags
}

# ---------------------------------------------------------------------------
# Backup selection for all resources tagged benchmark-backup = true
# ---------------------------------------------------------------------------
resource "aws_backup_selection" "tagged" {
  name         = "${local.name_prefix}-tagged-selection"
  plan_id      = aws_backup_plan.main.id
  iam_role_arn = aws_iam_role.backup.arn

  resources = ["*"]

  condition {
    string_equals {
      key   = "aws:ResourceTag/${local.backup_tag_key}"
      value = local.backup_tag_value
    }
  }
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  name_prefix = "cognito-mobile"

  user_pool_name = "${local.name_prefix}-user-pool"
  app_client_name = "${local.name_prefix}-app-client"
  identity_pool_name = "${local.name_prefix}-identity-pool"
  authenticated_role_name = "${local.name_prefix}-authenticated-role"

  # ARNs used for least-privilege scoping of the authenticated role policies.
  cognito_sync_arn = "arn:${data.aws_partition.current.partition}:cognito-sync:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:identitypool/${aws_cognito_identity_pool.main.id}"

  cognito_identity_arn = "arn:${data.aws_partition.current.partition}:cognito-identity:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:identitypool/${aws_cognito_identity_pool.main.id}"

  tags = {
    Project     = local.name_prefix
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

###############################################################################
# Cognito User Pool
###############################################################################

resource "aws_cognito_user_pool" "main" {
  name = local.user_pool_name

  username_attributes      = ["email"]
  auto_verified_attributes = ["email"]

  mfa_configuration = "OPTIONAL"

  software_token_mfa_configuration {
    enabled = true
  }

  password_policy {
    minimum_length                   = 12
    require_lowercase                = true
    require_uppercase                = true
    require_numbers                  = true
    require_symbols                  = true
    temporary_password_validity_days = 7
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }

  admin_create_user_config {
    allow_admin_create_user_only = false
  }

  schema {
    name                = "email"
    attribute_data_type = "String"
    required            = true
    mutable             = true

    string_attribute_constraints {
      min_length = 5
      max_length = 254
    }
  }

  tags = local.tags
}

###############################################################################
# Cognito User Pool App Client
###############################################################################

resource "aws_cognito_user_pool_client" "app" {
  name         = local.app_client_name
  user_pool_id = aws_cognito_user_pool.main.id

  generate_secret = false

  explicit_auth_flows = [
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
  ]

  prevent_user_existence_errors = "ENABLED"

  access_token_validity  = 1
  id_token_validity      = 1
  refresh_token_validity = 30

  token_validity_units {
    access_token  = "hours"
    id_token      = "hours"
    refresh_token = "days"
  }

  supported_identity_providers = ["COGNITO"]
}

###############################################################################
# Cognito Identity Pool linked to the User Pool
###############################################################################

resource "aws_cognito_identity_pool" "main" {
  identity_pool_name               = local.identity_pool_name
  allow_unauthenticated_identities = false
  allow_classic_flow               = false

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.app.id
    provider_name           = aws_cognito_user_pool.main.endpoint
    server_side_token_check = false
  }

  tags = local.tags
}

###############################################################################
# IAM role assumed by authenticated Cognito identities
###############################################################################

data "aws_iam_policy_document" "authenticated_assume_role" {
  statement {
    sid     = "AllowCognitoAuthenticatedIdentities"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.main.id]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["authenticated"]
    }
  }
}

resource "aws_iam_role" "authenticated" {
  name                 = local.authenticated_role_name
  description          = "Role assumed by authenticated identities in the ${local.identity_pool_name} identity pool"
  assume_role_policy   = data.aws_iam_policy_document.authenticated_assume_role.json
  max_session_duration = 3600

  tags = local.tags
}

data "aws_iam_policy_document" "authenticated_permissions" {
  statement {
    sid       = "CognitoSyncAccess"
    effect    = "Allow"
    actions   = ["cognito-sync:*"]
    resources = ["${local.cognito_sync_arn}/*"]
  }

  statement {
    sid       = "CognitoIdentityAccess"
    effect    = "Allow"
    actions   = ["cognito-identity:*"]
    resources = [local.cognito_identity_arn]
  }

  statement {
    sid       = "MobileAnalyticsPutEvents"
    effect    = "Allow"
    actions   = ["mobileanalytics:PutEvents"]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "authenticated" {
  name   = "${local.name_prefix}-authenticated-policy"
  role   = aws_iam_role.authenticated.id
  policy = data.aws_iam_policy_document.authenticated_permissions.json
}

###############################################################################
# Attach the IAM role to the identity pool for authenticated identities
###############################################################################

resource "aws_cognito_identity_pool_roles_attachment" "main" {
  identity_pool_id = aws_cognito_identity_pool.main.id

  roles = {
    "authenticated" = aws_iam_role.authenticated.arn
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_cidr            = "10.0.0.0/16"
  subnet_cidr         = "10.0.1.0/24"
  public_dns_servers  = ["8.8.8.8", "8.8.4.4"]
  common_tags = {
    Project     = "custom-test-vpc"
    Environment = "test"
    ManagedBy   = "Terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "custom-test-vpc"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_subnet" "main" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "custom-test-subnet"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "custom-test-igw"
  })
}

resource "aws_eip" "main" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "custom-test-eip"
  })
}

resource "aws_vpc_dhcp_options" "main" {
  domain_name         = "ec2.internal"
  domain_name_servers = local.public_dns_servers

  tags = merge(local.common_tags, {
    Name = "custom-test-dhcp-options"
  })
}

resource "aws_vpc_dhcp_options_association" "main" {
  vpc_id          = aws_vpc.main.id
  dhcp_options_id = aws_vpc_dhcp_options.main.id
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  ingress {
    description = "HTTP from within the VPC"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  ingress {
    description = "HTTPS from within the VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  ingress {
    description = "SSH from within the VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "Restrict egress to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "custom-test-default-sg"
  })
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  topic_name  = "event-topic"
  api_name    = "event-publisher-api"
  environment = "prod"

  common_tags = {
    Name        = local.api_name
    Environment = local.environment
    ManagedBy   = "terraform"
  }
}

###############################################################################
# KMS - dedicated customer managed key (CMK) with rotation for the SNS topic
###############################################################################

data "aws_iam_policy_document" "kms_key" {
  statement {
    sid    = "EnableRootAccountPermissions"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }
}

resource "aws_kms_key" "event_topic" {
  description             = "Customer managed key used to encrypt the ${local.topic_name} SNS topic"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key.json

  tags = merge(local.common_tags, { Name = "${local.topic_name}-kms" })
}

###############################################################################
# SNS topic encrypted with the dedicated CMK
###############################################################################

resource "aws_sns_topic" "event_topic" {
  name              = local.topic_name
  kms_master_key_id = aws_kms_key.event_topic.arn

  tags = local.common_tags
}

data "aws_iam_policy_document" "sns_topic" {
  statement {
    sid    = "AllowApiGatewayRoleToPublish"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.apigw_sns_publish.arn]
    }

    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.event_topic.arn]
  }

  statement {
    sid    = "AllowTopicOwnerManagement"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions = [
      "sns:GetTopicAttributes",
      "sns:SetTopicAttributes",
      "sns:AddPermission",
      "sns:RemovePermission",
      "sns:DeleteTopic",
      "sns:Subscribe",
      "sns:ListSubscriptionsByTopic",
      "sns:Publish",
    ]
    resources = [aws_sns_topic.event_topic.arn]
  }
}

resource "aws_sns_topic_policy" "event_topic" {
  arn    = aws_sns_topic.event_topic.arn
  policy = data.aws_iam_policy_document.sns_topic.json
}

###############################################################################
# IAM role that grants API Gateway permission to publish to the topic
###############################################################################

data "aws_iam_policy_document" "apigw_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["apigateway.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "apigw_sns_publish" {
  name               = "${local.api_name}-sns-publish"
  description        = "Allows API Gateway to publish messages to the ${local.topic_name} SNS topic"
  assume_role_policy = data.aws_iam_policy_document.apigw_assume_role.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "apigw_publish" {
  statement {
    sid       = "PublishToEventTopic"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.event_topic.arn]
  }

  statement {
    sid    = "UseKmsKeyForTopicEncryption"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:DescribeKey",
    ]
    resources = [aws_kms_key.event_topic.arn]
  }
}

resource "aws_iam_role_policy" "apigw_publish" {
  name   = "${local.api_name}-sns-publish"
  role   = aws_iam_role.apigw_sns_publish.id
  policy = data.aws_iam_policy_document.apigw_publish.json
}

###############################################################################
# API Gateway - REST API that proxies POST requests into the SNS topic
###############################################################################

resource "aws_api_gateway_rest_api" "events" {
  name        = local.api_name
  description = "Publishes incoming POST requests to the ${local.topic_name} SNS topic"

  endpoint_configuration {
    types = ["REGIONAL"]
  }

  tags = local.common_tags
}

resource "aws_api_gateway_resource" "events" {
  rest_api_id = aws_api_gateway_rest_api.events.id
  parent_id   = aws_api_gateway_rest_api.events.root_resource_id
  path_part   = "events"
}

resource "aws_api_gateway_method" "events_post" {
  rest_api_id   = aws_api_gateway_rest_api.events.id
  resource_id   = aws_api_gateway_resource.events.id
  http_method   = "POST"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "events_sns" {
  rest_api_id             = aws_api_gateway_rest_api.events.id
  resource_id             = aws_api_gateway_resource.events.id
  http_method             = aws_api_gateway_method.events_post.http_method
  type                    = "AWS"
  integration_http_method = "POST"
  uri                     = "arn:${data.aws_partition.current.partition}:apigateway:${data.aws_region.current.region}:sns:action/Publish"
  credentials             = aws_iam_role.apigw_sns_publish.arn

  request_parameters = {
    "integration.request.header.Content-Type" = "'application/json'"
  }

  request_templates = {
    "application/json" = <<-EOT
      {
        "TopicArn": "${aws_sns_topic.event_topic.arn}",
        "Message": "$util.escapeJavaScript($input.body)"
      }
    EOT
  }
}

resource "aws_api_gateway_method_response" "events_post_200" {
  rest_api_id = aws_api_gateway_rest_api.events.id
  resource_id = aws_api_gateway_resource.events.id
  http_method = aws_api_gateway_method.events_post.http_method
  status_code = "200"
}

resource "aws_api_gateway_integration_response" "events_sns_200" {
  rest_api_id = aws_api_gateway_rest_api.events.id
  resource_id = aws_api_gateway_resource.events.id
  http_method = aws_api_gateway_method.events_post.http_method
  status_code = aws_api_gateway_method_response.events_post_200.status_code

  depends_on = [aws_api_gateway_integration.events_sns]
}

resource "aws_api_gateway_deployment" "events" {
  rest_api_id = aws_api_gateway_rest_api.events.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_resource.events.id,
      aws_api_gateway_method.events_post.id,
      aws_api_gateway_integration.events_sns.id,
      aws_api_gateway_integration_response.events_sns_200.id,
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_api_gateway_integration.events_sns,
    aws_api_gateway_integration_response.events_sns_200,
  ]
}

resource "aws_api_gateway_stage" "events" {
  rest_api_id          = aws_api_gateway_rest_api.events.id
  deployment_id        = aws_api_gateway_deployment.events.id
  stage_name           = local.environment
  xray_tracing_enabled = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.api_access.arn
    format = jsonencode({
      requestId      = "$context.requestId"
      ip             = "$context.identity.sourceIp"
      requestTime    = "$context.requestTime"
      httpMethod     = "$context.httpMethod"
      resourcePath   = "$context.resourcePath"
      status         = "$context.status"
      responseLength = "$context.responseLength"
    })
  }

  tags = local.common_tags

  depends_on = [aws_api_gateway_account.this]
}

resource "aws_api_gateway_method_settings" "all" {
  rest_api_id = aws_api_gateway_rest_api.events.id
  stage_name  = aws_api_gateway_stage.events.stage_name
  method_path = "*/*"

  settings {
    metrics_enabled    = true
    logging_level      = "INFO"
    data_trace_enabled = false
  }

  depends_on = [aws_api_gateway_account.this]
}

###############################################################################
# CloudWatch logging for API Gateway
###############################################################################

resource "aws_cloudwatch_log_group" "api_access" {
  name              = "/aws/apigateway/${local.api_name}"
  retention_in_days = 30

  tags = local.common_tags
}

data "aws_iam_policy_document" "apigw_logging_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["apigateway.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "apigw_logging" {
  name               = "${local.api_name}-cloudwatch-logs"
  assume_role_policy = data.aws_iam_policy_document.apigw_logging_assume_role.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "apigw_logging" {
  role       = aws_iam_role.apigw_logging.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonAPIGatewayPushToCloudWatchLogs"
}

resource "aws_api_gateway_account" "this" {
  cloudwatch_role_arn = aws_iam_role.apigw_logging.arn
}
